local function centerFrame(f) f.Position = UDim2.new(0.5, -205, 0.5, -155) end

local vibracaoSuportada = false
pcall(function()
    vibracaoSuportada = HapticService:IsVibrationSupported(Enum.UserInputType.Touch)
end)

local function vibrar()
    if not vibracaoSuportada then return end
    task.spawn(function()
        pcall(function()
            HapticService:SetMotor(Enum.UserInputType.Touch, Enum.VibrationMotor.Small, 1)
            task.wait(0.03)
            HapticService:SetMotor(Enum.UserInputType.Touch, Enum.VibrationMotor.Small, 0)
        end)
    end)
end

local function addWhiteStroke(ui)
    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1.5
    stroke.Color = COR_BORDA
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = ui
end

local function aplicarScrollCustomizado(sf)
    sf.ScrollBarThickness = 0
    local track = Instance.new("Frame", sf)
    track.Name = "CustomTrack"
    track.Size = UDim2.new(0, 4, 1, -10)
    track.AnchorPoint = Vector2.new(1, 0)
    track.Position = UDim2.new(1, -6, 0, 5)
    track.BackgroundTransparency = 1
    track.BorderSizePixel = 0
    track.ZIndex = 10

    local thumb = Instance.new("Frame", track)
    thumb.Name = "Thumb"
    thumb.Size = UDim2.new(1, 0, 0, 10)
    thumb.BackgroundColor3 = COR_CARD
    thumb.BackgroundTransparency = 0.8
    thumb.BorderSizePixel = 0
    thumb.ZIndex = 11
    Instance.new("UICorner", thumb).CornerRadius = UDim.new(1, 0)

    local idleTimer = nil
    local ultimoUpdateVisual = 0

    local function resetIdleTimer()
        local agora = os.clock()
        -- Durante o arraste, apenas atualiza a posição do thumb.
        -- A animação de transparência fica limitada para não gerar
        -- dezenas de Tweens por segundo.
        if agora - ultimoUpdateVisual >= 0.12 then
            ultimoUpdateVisual = agora
            thumb.BackgroundTransparency = 0.2
        end

        if idleTimer then task.cancel(idleTimer) end
        idleTimer = task.delay(2.5, function()
            if thumb.Parent then
                thumb.BackgroundTransparency = 0.8
            end
        end)
    end

    local function atualizar()
        local cSize = sf.CanvasSize.Y.Offset
        local aSize = sf.AbsoluteSize.Y
        if cSize <= aSize then thumb.Visible = false; return end
        thumb.Visible = true
        local maxScroll = cSize - aSize
        local current = sf.CanvasPosition.Y
        local p = math.clamp(current / maxScroll, 0, 1)
        local maxThumbY = track.AbsoluteSize.Y - thumb.AbsoluteSize.Y
        thumb.Position = UDim2.new(0, 0, 0, p * maxThumbY)
    end

    sf:GetPropertyChangedSignal("CanvasPosition"):Connect(function() atualizar(); resetIdleTimer() end)
    sf:GetPropertyChangedSignal("CanvasSize"):Connect(atualizar)
    sf:GetPropertyChangedSignal("AbsoluteSize"):Connect(atualizar)
    task.spawn(function() task.wait(0.1); atualizar() end)
end

