-- Tabela para guardar a última moldura criada em cada aba
local ultimaMoldura = {}

local function criarMoldura(parent, posY, altura, tituloTexto)
    local m = Instance.new("Frame", parent)
    m.Size = UDim2.new(1, -20, 0, altura)
    
    -- Calcula o espaço de 5 pixels automaticamente
    local ultima = ultimaMoldura[parent]
    local novoY = posY
    if ultima and ultima.Parent == parent then
        novoY = ultima.Position.Y.Offset + ultima.Size.Y.Offset + 10
    end
    
    m.Position = UDim2.new(0, 10, 0, novoY) -- Aplica a nova posição
    ultimaMoldura[parent] = m -- Salva esta moldura como a última da aba
    
    m.BackgroundColor3 = COR_CARD
    m.BorderSizePixel = 0
    Instance.new("UICorner", m).CornerRadius = UDim.new(0, 10)
    addWhiteStroke(m)
    local tit = Instance.new("TextLabel", m)
    tit.Size = UDim2.new(1, -70, 0, 20)
    tit.Position = UDim2.new(0, 10, 0, 6)
    tit.BackgroundTransparency = 1
 tit.Text = tituloTexto
 tit.TextColor3 = COR_TEXTO
    tit.Font = FONTE_TITULO
 tit.TextSize = 13
 tit.TextXAlignment = Enum.TextXAlignment.Left
    return m
end

