    circle.Position = UDim2.new(0, 3, 0.5, -10)
    circle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    circle.BorderSizePixel = 0
    Instance.new("UICorner", circle).CornerRadius = UDim.new(1, 0)

    local btn = Instance.new("TextButton", moldura)
    btn.Size = UDim2.new(0, 48, 0, 26)
    btn.AnchorPoint = Vector2.new(1, 0.5)
    btn.Position = UDim2.new(1, -15, 0.5, 0)
    btn.BackgroundTransparency = 1
    btn.Text = ""
    return box, btn
end
local function criarToggle(moldura) return criarToggleDireita(moldura, 22) end

local function selecionarAba(aba)
    for _, c in ipairs(frame:GetChildren()) do
        local k = string.match(c.Name, "^ContainerAba_(.+)$")
        if k then c.Visible = (aba == k) end
    end
    for _, molduraAba in ipairs(sidebar:GetChildren()) do
        local k = string.match(molduraAba.Name, "^MolduraAba_(.+)$")
        local textoAba = molduraAba:FindFirstChild("BtnAba_" .. tostring(k))
        if k and textoAba then
            if aba == k then
                molduraAba.BackgroundColor3 = COR_BOTAO_ATIVO
                textoAba.TextColor3 = COR_TEXTO
            else
                molduraAba.BackgroundColor3 = COR_PAINEL
                textoAba.TextColor3 = COR_TEXTO_SUB
            end
        end
    end
end

