        -- Tradução robusta: executores diferentes expõem APIs HTTP diferentes.
        -- Tenta primeiro as funções de request do executor e depois as APIs Roblox.
        local cacheTraducoes = {}
        local function obterCorpoHttp(url)
            local resposta
            local funcaoRequest
            if type(syn) == "table" and type(syn.request) == "function" then
                funcaoRequest = syn.request
            elseif type(http) == "table" and type(http.request) == "function" then
                funcaoRequest = http.request
            elseif type(fluxus) == "table" and type(fluxus.request) == "function" then
                funcaoRequest = fluxus.request
            elseif type(http_request) == "function" then
                funcaoRequest = http_request
            elseif type(request) == "function" then
                funcaoRequest = request
            end

            if funcaoRequest then
                local ok, retorno = pcall(funcaoRequest, {Url = url, Method = "GET"})
                if ok and retorno then
                    if type(retorno) == "string" then
                        resposta = retorno
                    elseif type(retorno) == "table" then
                        if retorno.Success == false or (retorno.StatusCode and retorno.StatusCode >= 400) then
                            resposta = nil
                        else
                            resposta = retorno.Body or retorno.body
                        end
                    end
                end
            end

            if not resposta then
                local ok, retorno = pcall(function() return game:HttpGet(url) end)
                if ok and type(retorno) == "string" then resposta = retorno end
            end
            if not resposta then
                local ok, retorno = pcall(function() return HttpServiceIdioma:GetAsync(url) end)
                if ok and type(retorno) == "string" then resposta = retorno end
            end
            return resposta
        end

        local function traduzirTexto(texto, destino)
            if type(texto) ~= "string" or texto == "" or #texto > 450 then return texto end
            if texto:match("^%s*$") or texto:match("^[%d%p%s]+$") then return texto end
            local chaveCache = destino .. "\0" .. texto
            if cacheTraducoes[chaveCache] then return cacheTraducoes[chaveCache] end
            local url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=" .. destino .. "&dt=t&q=" .. HttpServiceIdioma:UrlEncode(texto)
            local bruto = obterCorpoHttp(url)
            if not bruto then return texto end
            local ok, resposta = pcall(function() return HttpServiceIdioma:JSONDecode(bruto) end)
            if not ok or type(resposta) ~= "table" or type(resposta[1]) ~= "table" then return texto end
            local partes = {}
            for _, trecho in ipairs(resposta[1]) do
                if type(trecho) == "table" and type(trecho[1]) == "string" then
                    table.insert(partes, trecho[1])
                end
            end
            local resultado = table.concat(partes)
            if resultado ~= "" then
                cacheTraducoes[chaveCache] = resultado
                return resultado
            end
            return texto
        end

        local function aplicarTextoTraduzido(obj, propriedade, original, destino)
            if not obj or not obj.Parent then return end
            if destino == "pt" then
                atualizandoTexto[obj] = true
                obj[propriedade] = original
                atualizandoTexto[obj] = nil
                return
            end
            table.insert(filaTraducao, {obj = obj, propriedade = propriedade, original = original, destino = destino})
            if workerAtivo then return end
            workerAtivo = true
            task.spawn(function()
                while #filaTraducao > 0 do
                    local item = table.remove(filaTraducao, 1)
                    if item.obj and item.obj.Parent and idiomaAtual == item.destino then
                        local traduzido = traduzirTexto(item.original, item.destino)
                        if idiomaAtual == item.destino and item.obj.Parent then
                            atualizandoTexto[item.obj] = true
                            item.obj[item.propriedade] = traduzido
                            atualizandoTexto[item.obj] = nil
                        end
                    end
                    task.wait(0.12)
                end
                workerAtivo = false
            end)
        end

        local function observarObjeto(obj)
            if not (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then return end
            if obj:GetAttribute("NaoTraduzir") then return end
            if textosOriginais[obj] == nil then textosOriginais[obj] = obj.Text end
            if obj:IsA("TextBox") and placeholdersOriginais[obj] == nil then
                placeholdersOriginais[obj] = obj.PlaceholderText
            end
            if not obj:GetAttribute("IdiomaMonitorado") then
                obj:SetAttribute("IdiomaMonitorado", true)
                obj:GetPropertyChangedSignal("Text"):Connect(function()
                    if atualizandoTexto[obj] then return end
                    textosOriginais[obj] = obj.Text
                    if idiomaAtual ~= "pt" then
                        aplicarTextoTraduzido(obj, "Text", textosOriginais[obj], idiomaAtual)
                    end
                end)
                if obj:IsA("TextBox") then
                    obj:GetPropertyChangedSignal("PlaceholderText"):Connect(function()
                        if atualizandoTexto[obj] then return end
                        placeholdersOriginais[obj] = obj.PlaceholderText
                        if idiomaAtual ~= "pt" then
                            aplicarTextoTraduzido(obj, "PlaceholderText", placeholdersOriginais[obj], idiomaAtual)
                        end
                    end)
                end
            end
            if idiomaAtual ~= "pt" then
                aplicarTextoTraduzido(obj, "Text", textosOriginais[obj], idiomaAtual)
                if obj:IsA("TextBox") and placeholdersOriginais[obj] and placeholdersOriginais[obj] ~= "" then
                    aplicarTextoTraduzido(obj, "PlaceholderText", placeholdersOriginais[obj], idiomaAtual)
                end
            end
        end

        local function selecionarIdioma(nome, codigo)
            vibrar()
            idiomaAtual = codigo
            nomeIdiomaAtual = nome
            idiomaSelecionadoLabel.Text = "Idioma atual: " .. nome
            escolherIdiomaBtn.Text = nome .. "  ▼"
            dropdownIdioma.Visible = false
            table.clear(filaTraducao)
            for _, obj in ipairs(gui:GetDescendants()) do
                if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                    if not obj:GetAttribute("NaoTraduzir") then
                        if textosOriginais[obj] == nil then textosOriginais[obj] = obj.Text end
                        aplicarTextoTraduzido(obj, "Text", textosOriginais[obj], codigo)
                        if obj:IsA("TextBox") then
                            if placeholdersOriginais[obj] == nil then placeholdersOriginais[obj] = obj.PlaceholderText end
                            if placeholdersOriginais[obj] ~= "" then
                                aplicarTextoTraduzido(obj, "PlaceholderText", placeholdersOriginais[obj], codigo)
                            end
                        end
                    end
                end
            end
        end

        local botoesIdioma = {}
        local function atualizarListaIdiomas(filtro)
            filtro = string.lower(filtro or "")
            for _, botao in ipairs(botoesIdioma) do
                local nome = string.lower(botao:GetAttribute("NomeIdioma") or "")
                botao.Visible = filtro == "" or string.find(nome, filtro, 1, true) ~= nil
            end
            task.defer(function()
                local total = 0
                for _, botao in ipairs(botoesIdioma) do if botao.Visible then total = total + 34 end end
                listaIdiomas.CanvasSize = UDim2.new(0, 0, 0, total)
            end)
        end

        for i, dados in ipairs(idiomas) do
            local nome, codigo = dados[1], dados[2]
            local botao = Instance.new("TextButton", listaIdiomas)
            botao.Size = UDim2.new(1, -4, 0, 30)
            botao.BackgroundColor3 = COR_PAINEL
            botao.Text = nome
            botao.TextColor3 = COR_TEXTO
            botao.Font = FONTE_TEXTO
            botao.TextSize = 12
            botao.LayoutOrder = i
            botao.ZIndex = 10002
            botao:SetAttribute("NomeIdioma", nome)
            botao:SetAttribute("NaoTraduzir", true)
            Instance.new("UICorner", botao).CornerRadius = UDim.new(0, 5)
            botao.MouseButton1Click:Connect(function() selecionarIdioma(nome, codigo) end)
            table.insert(botoesIdioma, botao)
        end
        layoutIdiomas:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            listaIdiomas.CanvasSize = UDim2.new(0, 0, 0, layoutIdiomas.AbsoluteContentSize.Y + 4)
        end)

        escolherIdiomaBtn.MouseButton1Click:Connect(function()
            vibrar()
            dropdownIdioma.Visible = true
            pesquisaIdioma.Text = ""
            atualizarListaIdiomas("")
        end)
        voltarIdiomaBtn.MouseButton1Click:Connect(function()
            vibrar()
            dropdownIdioma.Visible = false
            pesquisaIdioma.Text = ""
        end)
        pesquisaIdioma:GetPropertyChangedSignal("Text"):Connect(function()
            atualizarListaIdiomas(pesquisaIdioma.Text)
        end)

        gui.DescendantAdded:Connect(function(obj)
            task.defer(function()
                if obj and obj.Parent then observarObjeto(obj) end
            end)
        end)
        for _, obj in ipairs(gui:GetDescendants()) do observarObjeto(obj) end
        contIdiomas.CanvasSize = UDim2.new(0, 0, 0, 235)
    end
end
-- ===================== FIM IDIOMAS =====================

-- Um único padrão visual para TODOS os seletores com seta.
-- Reutiliza os controles e callbacks existentes; altera somente a apresentação.
local function aplicarPadraoDropdownIdiomas(popup, pesquisa, voltar, lista, placeholder)
    popup.Size = UDim2.new(0, 250, 0, 230)
    popup.Position = UDim2.new(0.5, -125, 0.5, -115)
    popup.BackgroundColor3 = COR_FUNDO
    popup.BorderSizePixel = 0
    popup.ZIndex = 10000
    popup.ClipsDescendants = true
    local cantoPopup = popup:FindFirstChildOfClass("UICorner")
    if cantoPopup then cantoPopup.CornerRadius = UDim.new(0, 10) end

    local function obterMoldura(controle, nome, altura, y, fundo)
        local moldura = controle.Parent
        if moldura == popup then
            moldura = Instance.new("Frame")
            moldura.Name = nome
            moldura.Parent = popup
            controle.Parent = moldura
        end
        moldura.Name = nome
        moldura.Size = UDim2.new(1, -12, 0, altura)
        moldura.Position = UDim2.new(0, 6, 0, y)
        moldura.BackgroundColor3 = fundo or COR_CARD
        moldura.BackgroundTransparency = (fundo == nil) and 1 or 0
        moldura.BorderSizePixel = 0
        moldura.ZIndex = 10001
        moldura.ClipsDescendants = true
        local canto = moldura:FindFirstChildOfClass("UICorner")
        if not canto then canto = Instance.new("UICorner", moldura) end
        canto.CornerRadius = UDim.new(0, 6)
        local stroke = moldura:FindFirstChildOfClass("UIStroke")
        if not stroke then
            stroke = Instance.new("UIStroke", moldura)
            stroke.Thickness = 1.5
            stroke.Transparency = 0
            table.insert(bordasRGBAbas, stroke)
        end
        for _, filho in ipairs(controle:GetChildren()) do
            if filho:IsA("UIStroke") or filho:IsA("UICorner") then filho:Destroy() end
        end
        controle.BorderSizePixel = 0
        controle.Size = UDim2.new(1, 0, 1, 0)
        controle.Position = UDim2.new(0, 0, 0, 0)
        controle.ZIndex = 10002
        return moldura
    end

    obterMoldura(pesquisa, "MolduraPesquisaDropdown", 30, 6, COR_CARD)
    pesquisa.BackgroundTransparency = 1
    pesquisa.TextColor3 = COR_TEXTO
    pesquisa.PlaceholderColor3 = COR_TEXTO_SUB
    pesquisa.PlaceholderText = placeholder or "Pesquisar..."
    pesquisa.TextXAlignment = Enum.TextXAlignment.Center
    pesquisa.TextSize = 12
    pesquisa.ClearTextOnFocus = false

    obterMoldura(voltar, "MolduraVoltarDropdown", 28, 42, nil)
    voltar.BackgroundTransparency = 1
    voltar.Text = "‹ Voltar"
    voltar.TextColor3 = COR_TEXTO
    voltar.Font = FONTE_TEXTO
    voltar.TextSize = 12

    lista.Size = UDim2.new(1, -12, 1, -78)
    lista.Position = UDim2.new(0, 6, 0, 74)
    lista.BackgroundTransparency = 1
    lista.BorderSizePixel = 0
    lista.ScrollBarThickness = 3
    lista.ZIndex = 10001
    lista.ClipsDescendants = true
end

-- ===================== TEMAS (ABA TEMAS) =====================
