task.spawn(function()
    task.wait(0.15)
    for _, dot in ipairs(bolinhasVerdes) do
        if dot.Parent then
            local us = dot:FindFirstChildOfClass("UIScale")
            if us then
                local tweenInfo = TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
                TweenService:Create(us, tweenInfo, {Scale = 1.5}):Play()
            end
        end
    end
end)

-- Controle exclusivo de rolagem: cada gesto pertence somente à área
-- em que começou. As outras áreas ficam bloqueadas durante esse gesto.
local areaScrollAtiva = nil

local function pontoDentroDoObjeto(pos, objeto)
    if not objeto or not objeto.Visible then return false end
    local canto = objeto.AbsolutePosition
    local tamanho = objeto.AbsoluteSize
    return pos.X >= canto.X and pos.X <= canto.X + tamanho.X
       and pos.Y >= canto.Y and pos.Y <= canto.Y + tamanho.Y
end

local function definirAreaScroll(pos)
    local alvo = nil
    if pontoDentroDoObjeto(pos, sidebar) then
        alvo = sidebar
    else
        for _, cont in ipairs(contentScrolls) do
            if pontoDentroDoObjeto(pos, cont) then
                alvo = cont
                break
            end
        end
    end

    areaScrollAtiva = alvo
    sidebar.ScrollingEnabled = (alvo == sidebar)
    for _, cont in ipairs(contentScrolls) do
        cont.ScrollingEnabled = (alvo == cont)
    end
end

-- Inicialmente, somente a lista lateral fica habilitada; o conteúdo ativo
-- será habilitado quando o usuário iniciar o gesto dentro dele.
sidebar.ScrollingEnabled = true
for _, cont in ipairs(contentScrolls) do
    cont.ScrollingEnabled = false
end

UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.Touch
        or input.UserInputType == Enum.UserInputType.MouseButton1 then
        definirAreaScroll(input.Position)
    end
end)

-- A roda do mouse também é direcionada à área sob o cursor.
UserInputService.InputChanged:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseWheel then
        definirAreaScroll(UserInputService:GetMouseLocation())
    end
end)

UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.Touch
        or input.UserInputType == Enum.UserInputType.MouseButton1 then
        -- Mantém as áreas não selecionadas bloqueadas após soltar o toque.
        -- O próximo gesto escolhe novamente a área pelo ponto inicial.
        if areaScrollAtiva == nil then
            sidebar.ScrollingEnabled = true
            for _, cont in ipairs(contentScrolls) do
                cont.ScrollingEnabled = false
            end
        end
    end
end)

