-- Posição persistente e movimentação do contador FPS.
local FPS_POS_FILE = "CelestialHub_FPSPosition.txt"
local function salvarPosicaoFPS()
    pcall(function()
        if writefile then
            writefile(FPS_POS_FILE, tostring(math.floor(fpsOverlay.Position.X.Offset)) .. "," .. tostring(math.floor(fpsOverlay.Position.Y.Offset)))
        end
    end)
end

pcall(function()
    if isfile and readfile and isfile(FPS_POS_FILE) then
        local conteudo = readfile(FPS_POS_FILE)
        local x, y = tostring(conteudo):match("^%s*(-?%d+)%s*,%s*(-?%d+)%s*$")
        x, y = tonumber(x), tonumber(y)
        if x and y then
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new( math.huge, math.huge )
            x = math.clamp(x, 0, math.max(0, viewport.X - fpsOverlay.AbsoluteSize.X))
            y = math.clamp(y, 0, math.max(0, viewport.Y - fpsOverlay.AbsoluteSize.Y))
            fpsOverlay.Position = UDim2.new(0, x, 0, y)
        end
    end
end)

local fpsArrastando = false
local fpsInputInicial = nil
local fpsPosicaoInicial = nil

fpsOverlay.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        fpsArrastando = true
        fpsInputInicial = input.Position
        fpsPosicaoInicial = fpsOverlay.Position
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                fpsArrastando = false
                salvarPosicaoFPS()
            end
        end)
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if not fpsArrastando then return end
    if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then return end

    local delta = input.Position - fpsInputInicial
    local x = fpsPosicaoInicial.X.Offset + delta.X
    local y = fpsPosicaoInicial.Y.Offset + delta.Y
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(0, 0)
    x = math.clamp(x, 0, math.max(0, viewport.X - fpsOverlay.AbsoluteSize.X))
    y = math.clamp(y, 0, math.max(0, viewport.Y - fpsOverlay.AbsoluteSize.Y))
    fpsOverlay.Position = UDim2.new(0, x, 0, y)
end)

local fpsMostrando = false
local fpsFrameCount = 0
local fpsUltimoTempo = os.clock()

RunService.RenderStepped:Connect(function()
    if not fpsMostrando then return end
    fpsFrameCount = fpsFrameCount + 1
    local agora = os.clock()
    local delta = agora - fpsUltimoTempo
    if delta >= 1 then
        local fps = math.floor(fpsFrameCount / delta)
 fpsOverlay.Text = "FPS: " .. fps
        if fps >= 50 then
 fpsOverlay.TextColor3 = Color3.fromRGB(0, 255, 0)
        elseif fps >= 30 then
 fpsOverlay.TextColor3 = Color3.fromRGB(255, 220, 0)
        else
 fpsOverlay.TextColor3 = Color3.fromRGB(255, 60, 60)
        end
        fpsFrameCount = 0
        fpsUltimoTempo = agora
    end
end)
