local HttpService = game:GetService("HttpService")
local TeleportService = game:GetService("TeleportService")
local hopEmAndamento = false

local function hopServer()
    if hopEmAndamento then return end
    hopEmAndamento = true
    hopStatus.TextColor3 = Color3.fromRGB(255, 200, 80)
    hopStatus.Text = "Procurando servidor..."

    task.spawn(function()
        local success, result = pcall(function()
            local resposta = game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100")
            local data = HttpService:JSONDecode(resposta)
            if not data or type(data.data) ~= "table" then
                error("Resposta inválida")
            end
            return data
        end)

        if success and result then
            local achou = false
            for _, server in ipairs(result.data) do
                if server.playing < server.maxPlayers and server.id ~= game.JobId then
                    achou = true
                    hopStatus.TextColor3 = Color3.fromRGB(0, 220, 0)
                    hopStatus.Text = "Teleportando..."
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, player)
                    break
                end
            end

            if not achou then
                hopStatus.TextColor3 = COR_ALERTA
                hopStatus.Text = "Nenhum servidor livre encontrado."
                hopEmAndamento = false
            end
        else
            hopStatus.TextColor3 = COR_ALERTA
            hopStatus.Text = "Erro ao buscar servidores."
            hopEmAndamento = false
        end
    end)
end

hopNowBtn.MouseButton1Click:Connect(function()
    vibrar()
    hopServer()
end)
