 marineBtn.Text = textoMarinhaOriginal .. " (" .. restante .. "s)"
                    task.wait(0.1)
                end

 pirateBtn.Text = textoPirataOriginal
 marineBtn.Text = textoMarinhaOriginal
                pirateBtn.BackgroundColor3 = corPirataOriginal
                marineBtn.BackgroundColor3 = corMarinhaOriginal
                pirateBtn.AutoButtonColor = true
                marineBtn.AutoButtonColor = true
                pirateBtn.Active = true
                marineBtn.Active = true
                teamCooldownAtivo = false
            end)

            return true
        end

