        local sessaoInicioClock = os.clock()

        local function formatar24h(segundos)
            segundos = math.max(0, math.floor(segundos))
            local dias    = math.floor(segundos / 86400)
            local horas   = math.floor((segundos % 86400) / 3600)
            local minutos = math.floor((segundos % 3600) / 60)
            local segs    = segundos % 60

            if dias > 0 then
                return string.format("%dd %02d:%02d:%02d", dias, horas, minutos, segs)
            else
                return string.format("%02d:%02d:%02d", horas, minutos, segs)
            end
        end

        task.spawn(function()
            while gui.Parent do
                local sessaoSeg = os.clock() - sessaoInicioClock
 textoSessao.Text = formatar24h(sessaoSeg)
                task.wait(1)
            end
        end)
    end
end

