        local function criarCDLabel(botao, textSize)
            local cd = Instance.new("TextLabel", botao)
            cd.Size = UDim2.new(1, 0, 1, 0)
            cd.BackgroundColor3 = Color3.fromRGB(20, 20, 30)
            cd.BackgroundTransparency = 0.35
 cd.Text = ""
 cd.TextColor3 = Color3.fromRGB(0, 255, 0)
            cd.Font = FONTE_TEXTO
 cd.TextSize = textSize or 24
 cd.TextStrokeTransparency = 0
 cd.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            cd.ZIndex = 10
            cd.Visible = false
            cd.Active = false
            Instance.new("UICorner", cd).CornerRadius = UDim.new(0, 8)
            return cd
        end
        local cdMenos = criarCDLabel(btnMenos, 24)
        local cdNormal = criarCDLabel(btnNormal, 18)
        local cdMais = criarCDLabel(btnMais, 24)

        local function atualizarVisualBotoes()
 if emPrimeiraPessoa then btnMenos.BackgroundColor3 = COR_BOTAO_DESABILITADO; btnMenos.TextColor3 = COR_TEXTO_SUB
 else btnMenos.BackgroundColor3 = COR_BOTAO_ATIVO; btnMenos.TextColor3 = COR_TEXTO end
 if noMaximo then btnMais.BackgroundColor3 = COR_BOTAO_DESABILITADO; btnMais.TextColor3 = COR_TEXTO_SUB
 else btnMais.BackgroundColor3 = COR_BOTAO_ATIVO; btnMais.TextColor3 = COR_TEXTO end
        end

        local function iniciarCooldownCompartilhado(botaoClicado)
            zoomCooldown = true
            btnMenos.Active = false
            btnNormal.Active = false
            btnMais.Active = false
            local cdLabel
            if botaoClicado == btnMenos then cdLabel = cdMenos
            elseif botaoClicado == btnNormal then cdLabel = cdNormal
            else cdLabel = cdMais end
            cdLabel.Visible = true
            task.spawn(function()
 for i = COOLDOWN_SEG, 1, -1 do cdLabel.Text = tostring(i); task.wait(1) end
 cdLabel.Text = ""
                cdLabel.Visible = false
                zoomCooldown = false
                if not emPrimeiraPessoa then btnMenos.Active = true end
                btnNormal.Active = true
                if not noMaximo then btnMais.Active = true end
            end)
        end

        btnMenos.MouseButton1Click:Connect(function()
            if zoomCooldown or emPrimeiraPessoa then return end
            vibrar()
            zoomToken = zoomToken + 1
            pcall(function()
                player.CameraMode = Enum.CameraMode.LockFirstPerson
                player.CameraMinZoomDistance = 0.5
                player.CameraMaxZoomDistance = 0.5
            end)
            emPrimeiraPessoa = true
            noMaximo = false
 zoomLabel.Text = "Zoom: Primeira Pessoa"
            atualizarVisualBotoes()
            iniciarCooldownCompartilhado(btnMenos)
        end)

        btnMais.MouseButton1Click:Connect(function()
            if zoomCooldown or noMaximo then return end
            vibrar()
            zoomToken = zoomToken + 1
            local tokenAtual = zoomToken
            pcall(function() player.CameraMode = Enum.CameraMode.Classic end)
            task.spawn(function()
                local passos = 20
                local delay = 0.4 / passos
                local inicial = player.CameraMaxZoomDistance
                local alvo = ORIG_MAX
                for i = 1, passos do
                    if zoomToken ~= tokenAtual then return end
                    local t = i / passos
                    local v = inicial + (alvo - inicial) * t
                    pcall(function() player.CameraMinZoomDistance = v; player.CameraMaxZoomDistance = v end)
                    task.wait(delay)
                end
                if zoomToken == tokenAtual then
                    pcall(function() player.CameraMinZoomDistance = alvo; player.CameraMaxZoomDistance = alvo end)
                end
            end)
            emPrimeiraPessoa = false
            noMaximo = true
 zoomLabel.Text = "Zoom: Máximo"
            atualizarVisualBotoes()
            iniciarCooldownCompartilhado(btnMais)
        end)

        btnNormal.MouseButton1Click:Connect(function()
            if zoomCooldown then return end
            vibrar()
            zoomToken = zoomToken + 1
            local tokenAtual = zoomToken
            emPrimeiraPessoa = false
            noMaximo = false
 zoomLabel.Text = "Zoom: Normal"
            atualizarVisualBotoes()
            iniciarCooldownCompartilhado(btnNormal)

            pcall(function()
                player.CameraMode = Enum.CameraMode.Classic
                local char = player.Character
                if char then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum then hum.CameraOffset = Vector3.new(0, 0, 0) end
                end
            end)

            task.spawn(function()
                local passos = 20
                local delay = 0.4 / passos
                local inicial = player.CameraMaxZoomDistance or ZOOM_PADRAO
                local alvo = ZOOM_PADRAO
                for i = 1, passos do
                    if zoomToken ~= tokenAtual then return end
                    local t = i / passos
                    local v = inicial + (alvo - inicial) * t
                    pcall(function() player.CameraMinZoomDistance = v; player.CameraMaxZoomDistance = v end)
                    task.wait(delay)
                end
            end)

            task.spawn(function()
                task.wait(0.5)
                if zoomToken ~= tokenAtual then return end
                local inicio = tick()
                while tick() - inicio < 2.5 and zoomToken == tokenAtual do
                    pcall(function()
                        if player.CameraMode ~= Enum.CameraMode.Classic then player.CameraMode = Enum.CameraMode.Classic end
                        if player.CameraMinZoomDistance > ORIG_MIN + 0.5 then player.CameraMinZoomDistance = ORIG_MIN end
                        if player.CameraMaxZoomDistance < ORIG_MAX - 0.5 then player.CameraMaxZoomDistance = ORIG_MAX end
                        local cam = workspace.CurrentCamera
                        if cam then cam.CameraType = Enum.CameraType.Custom end
                        local char = player.Character
                        if char then
                            local hum = char:FindFirstChildOfClass("Humanoid")
                            if hum then hum.CameraOffset = Vector3.new(0, 0, 0) end
                        end
                    end)
                    task.wait(0.05)
                end
            end)
        end)

        atualizarVisualBotoes()
        contZoom.CanvasSize = UDim2.new(0, 0, 0, 310)
    end
end
