        semBrilhoMsg.TextWrapped = true
        semBrilhoMsg.TextXAlignment = Enum.TextXAlignment.Center

        local semBrilhoAtivo = false
        local estadosLuzesSemBrilho = {}
        local semBrilhoDescendantConn = nil

        local function pertenceAJogador(obj)
            local modelo = obj:FindFirstAncestorOfClass("Model")
            if not modelo then return false end
            for _, jogador in ipairs(PlayersService:GetPlayers()) do
                if jogador.Character == modelo then
                    return true
                end
            end
            return false
        end

        local function aplicarSemBrilho(obj)
            if not semBrilhoAtivo or not obj or not obj:IsA("Light") then return end
            if pertenceAJogador(obj) then return end
            if estadosLuzesSemBrilho[obj] == nil then
                estadosLuzesSemBrilho[obj] = obj.Enabled
            end
            obj.Enabled = false
        end

        local function ativarSemBrilho()
            semBrilhoAtivo = true

            task.spawn(function()
                local lista = workspace:GetDescendants()
                local lote = 0

                for _, obj in ipairs(lista) do
                    if not semBrilhoAtivo then break end
                    aplicarSemBrilho(obj)
                    lote += 1

                    if lote >= 150 then
                        lote = 0
                        task.wait()
                    end
                end
            end)

            semBrilhoDescendantConn = workspace.DescendantAdded:Connect(function(obj)
                if semBrilhoAtivo then
                    task.defer(function()
                        aplicarSemBrilho(obj)
                    end)
                end
            end)
            semBrilhoBtn.Text = "DESATIVAR SEM BRILHO"
            semBrilhoBtn.BackgroundColor3 = COR_BOTAO_ATIVO
            semBrilhoMsg.TextColor3 = Color3.fromRGB(0, 220, 0)
            semBrilhoMsg.Text = "Luzes artificiais do cenário desativadas."
        end

        local function desativarSemBrilho()
            semBrilhoAtivo = false
            if semBrilhoDescendantConn then
                semBrilhoDescendantConn:Disconnect()
                semBrilhoDescendantConn = nil
            end
            for luz, estadoOriginal in pairs(estadosLuzesSemBrilho) do
                pcall(function()
                    if luz and luz.Parent then
                        luz.Enabled = estadoOriginal
                    end
                end)
            end
            estadosLuzesSemBrilho = {}
            semBrilhoBtn.Text = "ATIVAR SEM BRILHO"
            semBrilhoBtn.BackgroundColor3 = COR_BOTAO_INATIVO
            semBrilhoMsg.TextColor3 = COR_TEXTO_SUB
            semBrilhoMsg.Text = "Iluminação original restaurada."
        end

        semBrilhoBtn.MouseButton1Click:Connect(function()
            vibrar()
            if semBrilhoAtivo then
                desativarSemBrilho()
            else
                ativarSemBrilho()
            end
        end)

        -- Ativa automaticamente assim que esta seção do script é criada.
        ativarSemBrilho()
        -- ===================== FIM SEM BRILHO =====================

