        local function executarLimpeza()
    local limpos = 0
    for _, v in ipairs(workspace:GetChildren()) do
        pcall(function()
            if v:IsA("Part") and not v:FindFirstAncestorOfClass("Model") then
                if v.Name ~= "Baseplate" and v.Name ~= "Part" and v.Name ~= "SpawnLocation" then
                    v:Destroy()
                    limpos = limpos + 1
                end
            end
        end)
    end
 lixoMsg.TextColor3 = Color3.fromRGB(0, 220, 0)
 lixoMsg.Text = " " .. limpos .. " objetos limpos!"
end

lixoBtn.MouseButton1Click:Connect(function()
    vibrar()
    executarLimpeza()
end)

