        local function ativarTudoBatata()
            modoBatataAtivo = true
            pcall(function() settings().Rendering.QualityLevel = 21 end)
            pcall(function() setfflag("DFIntDebugFRMQualityLevelOverride", "21") end)
            pcall(function()
                Lighting.GlobalShadows = false
                Lighting.EnvironmentDiffuseScale = 0
                Lighting.EnvironmentSpecularScale = 0
            end)
            for _, v in ipairs(Lighting:GetChildren()) do
                pcall(function()
                    if v:IsA("BloomEffect") or v:IsA("SunRaysEffect") or v:IsA("BlurEffect") or v:IsA("DepthOfFieldEffect") then
                        v.Enabled = false
                    end
                end)
            end
            pcall(function()
                workspace.Terrain.WaterWaveSize = 0
                workspace.Terrain.WaterWaveSpeed = 0
                workspace.Terrain.WaterReflectance = 0
                workspace.Terrain.WaterTransparency = 1
            end)
            task.spawn(function()
                local lista = workspace:GetDescendants()
                local lote = 0

                for _, v in ipairs(lista) do
                    if not modoBatataAtivo then break end

                    pcall(function()
                        if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles") then
                            if v:GetAttribute("OldBatataEnabled") == nil then v:SetAttribute("OldBatataEnabled", v.Enabled) end
                            v.Enabled = false
                        elseif v:IsA("Decal") or v:IsA("Texture") then
                            if v:GetAttribute("OldBatataTrans") == nil then v:SetAttribute("OldBatataTrans", v.Transparency) end
                            v.Transparency = 1
                        elseif v:IsA("BasePart") then
                            if v:GetAttribute("OldBatataMat") == nil then
                                v:SetAttribute("OldBatataMat", v.Material)
                                v:SetAttribute("OldBatataCast", v.CastShadow)
                                v:SetAttribute("OldBatataRef", v.Reflectance)
                            end
                            v.Material = Enum.Material.SmoothPlastic
                            v.CastShadow = false
                            v.Reflectance = 0
                        end
                    end)

                    lote += 1
                    if lote >= 150 then
                        lote = 0
                        task.wait()
                    end
                end
            end)
            loopAcessorios = task.spawn(function()
                while modoBatataAtivo do
                    for _, plr in ipairs(PlayersService:GetPlayers()) do
                        if plr ~= player and plr.Character then
                            for _, v in ipairs(plr.Character:GetDescendants()) do
                                pcall(function()
                                    if v:IsA("Accessory") or v:IsA("Hat") or (v:IsA("MeshPart") and v.Name:lower():find("hair")) then
                                        if v:FindFirstChild("Handle") then v.Handle.Transparency = 1
                                        else v.Transparency = 1 end
                                    end
                                end)
                            end
                        end
                    end
                    task.wait(1)
                end
            end)
            loopEfeitos = task.spawn(function()
                while modoBatataAtivo do
                    for _, v in ipairs(workspace:GetDescendants()) do
                        pcall(function()
                            if v:IsA("ParticleEmitter") or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles") then
                                v.Enabled = false
                            end
                        end)
                    end
                    task.wait(2.5)
                end
            end)
            loopTexturas = task.spawn(function()
                while modoBatataAtivo do
                    for _, v in ipairs(workspace:GetDescendants()) do
                        pcall(function()
                            if v:IsA("Decal") or v:IsA("Texture") then
                                v.Transparency = 1
                            end
                        end)
                    end
                    task.wait(3)
                end
            end)
            loopAnimacoes = task.spawn(function()
                while modoBatataAtivo do
                    for _, plr in ipairs(PlayersService:GetPlayers()) do
                        if plr ~= player and plr.Character then
                            local animate = plr.Character:FindFirstChild("Animate")
                            if animate then animate:Destroy() end
                        end
                    end
                    task.wait(2)
                end
            end)
        end

        local function desativarTudoBatata()
            modoBatataAtivo = false
            if loopAcessorios then task.cancel(loopAcessorios); loopAcessorios = nil end
            if loopEfeitos then task.cancel(loopEfeitos); loopEfeitos = nil end
            if loopTexturas then task.cancel(loopTexturas); loopTexturas = nil end
            if loopAnimacoes then task.cancel(loopAnimacoes); loopAnimacoes = nil end
            pcall(function() settings().Rendering.QualityLevel = 21 end)
            pcall(function() setfflag("DFIntDebugFRMQualityLevelOverride", "21") end)
            pcall(function()
                Lighting.GlobalShadows = true
                Lighting.EnvironmentDiffuseScale = 1
                Lighting.EnvironmentSpecularScale = 1
            end)
            for _, v in ipairs(Lighting:GetChildren()) do
                pcall(function()
                    if v:IsA("BloomEffect") or v:IsA("SunRaysEffect") or v:IsA("BlurEffect") or v:IsA("DepthOfFieldEffect") then
                        v.Enabled = true
                    end
                end)
            end
            pcall(function()
                workspace.Terrain.WaterWaveSize = 0.15
                workspace.Terrain.WaterWaveSpeed = 10
                workspace.Terrain.WaterReflectance = 1
                workspace.Terrain.WaterTransparency = 0.5
            end)
            task.spawn(function()
                for _, v in pairs(workspace:GetDescendants()) do
                    pcall(function()
                        if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles") then
                            if v:GetAttribute("OldBatataEnabled") ~= nil then v.Enabled = v:GetAttribute("OldBatataEnabled") end
                        elseif v:IsA("Decal") or v:IsA("Texture") then
                            if v:GetAttribute("OldBatataTrans") ~= nil then v.Transparency = v:GetAttribute("OldBatataTrans") end
                        elseif v:IsA("BasePart") then
                            if v:GetAttribute("OldBatataMat") ~= nil then
                                v.Material = v:GetAttribute("OldBatataMat")
                                v.CastShadow = v:GetAttribute("OldBatataCast")
                                v.Reflectance = v:GetAttribute("OldBatataRef")
                            end
                        end
                    end)
                end
            end)
        end

