        local function getIlhaPosicao(ilha)
            if ilha:IsA("BasePart") then return ilha.Position
            elseif ilha:IsA("Model") then
                local ok, cf = pcall(function() return ilha:GetBoundingBox() end)
                if ok and cf then return cf.Position end
                local ok2, pivot = pcall(function() return ilha:GetPivot() end)
                if ok2 and pivot then return pivot.Position end
            end
            return nil
        end
        local function criarBillboardIlha(nome, ilha)
            local pos = getIlhaPosicao(ilha)
            if not pos then return end
            local anchor = Instance.new("Part")
            anchor.Name = nome
            anchor.Size = Vector3.new(1, 1, 1)
            anchor.Transparency = 1
            anchor.CanCollide = false
            anchor.CanQuery = false
            anchor.CanTouch = false
            anchor.Anchored = true
            anchor.Parent = ilhasPasta
            anchor.CFrame = CFrame.new(pos + Vector3.new(0, 20, 0))
            local bb = Instance.new("BillboardGui")
            bb.Name = "ILHA_" .. nome
            bb.Adornee = anchor
            bb.AlwaysOnTop = true
            bb.Size = UDim2.new(0, 200, 0, 40)
