 lbl.Text = nome
 lbl.TextColor3 = COR_ILHA
 lbl.TextStrokeTransparency = 0
 lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            lbl.Font = FONTE_TEXTO
 lbl.TextSize = 14
            ilhasTags[nome] = { bb = bb, lbl = lbl, anchor = anchor, nome = nome, ilha = ilha, ultimaDist = -1 }
        end
        local function escanearIlhas()
            local porNome = {}
            for _, obj in ipairs(workspace:GetChildren()) do
                if (obj:IsA("Model") or obj:IsA("BasePart")) and not ilhasTags[obj.Name] then porNome[obj.Name] = obj end
            end
            for _, nome in ipairs(NOMES_ILHAS) do
                if not ilhasTags[nome] and porNome[nome] then pcall(criarBillboardIlha, nome, porNome[nome]) end
            end
            local faltam = false
            for _, nome in ipairs(NOMES_ILHAS) do if not ilhasTags[nome] then faltam = true; break end end
            if faltam then
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("Model") or obj:IsA("BasePart") then
                        for _, nome in ipairs(NOMES_ILHAS) do
