        local function lerEnergiaSpawnNew(p, character)
            local nomesValor = {"N", "Energia", "Energy", "Shield", "Escudo", "Mana"}
            local nomesMax = {"MaxN", "NMax", "MaxEnergia", "MaxEnergy", "MaxShield", "MaxEscudo", "MaxMana"}
            local fontes = {character, p}
            local valorAtual, valorMax
            for _, fonte in ipairs(fontes) do
                if fonte then
                    for _, nomeValor in ipairs(nomesValor) do
                        local atributo = fonte:GetAttribute(nomeValor)
                        if typeof(atributo) == "number" then valorAtual = atributo; break end
                        local objeto = fonte:FindFirstChild(nomeValor, true)
                        if objeto and (objeto:IsA("NumberValue") or objeto:IsA("IntValue")) then
                            valorAtual = objeto.Value; break
                        end
                    end
                    if valorAtual ~= nil then break end
                end
            end
            for _, fonte in ipairs(fontes) do
                if fonte then
                    for _, nomeMaximo in ipairs(nomesMax) do
                        local atributo = fonte:GetAttribute(nomeMaximo)
                        if typeof(atributo) == "number" then valorMax = atributo; break end
                        local objeto = fonte:FindFirstChild(nomeMaximo, true)
                        if objeto and (objeto:IsA("NumberValue") or objeto:IsA("IntValue")) then
                            valorMax = objeto.Value; break
                        end
                    end
                    if valorMax ~= nil then break end
                end
            end
            if valorAtual == nil then return nil, nil end
            return math.max(0, valorAtual), math.max(1, tonumber(valorMax) or 100)
        end

        local function atualizarTagsSpawnNew()
            local charLocal = player.Character
            local rootLocal = charLocal and (charLocal:FindFirstChild("HumanoidRootPart") or charLocal:FindFirstChild("Head"))
            if not rootLocal then return end

            for p, tag in pairs(spawnNewTags) do
                if not p.Parent or not tag.head or not tag.head.Parent or not tag.humanoid or not tag.humanoid.Parent then
                    removerTagSpawnNew(p)
                else
                    local nivel = nivelDoJogador(p)
                    local distancia = math.floor((tag.head.Position - rootLocal.Position).Magnitude)
                    local nomeVisivel = p.DisplayName ~= "" and p.DisplayName or p.Name
                    local nivelTexto = nivel and (" [Lv. " .. nivel .. "]") or ""
                    tag.nome.Text = nomeVisivel .. " (@" .. p.Name .. ")" .. nivelTexto .. " - " .. distancia .. "m"

                    local maxVida = math.max(tag.humanoid.MaxHealth, 1)
                    local vida = math.clamp(tag.humanoid.Health, 0, maxVida)
                    local proporcao = vida / maxVida
                    tag.barraVida.Size = UDim2.new(proporcao, 0, 1, 0)
                    tag.barraVida.BackgroundColor3 = proporcao > 0.6
                        and Color3.fromRGB(50, 230, 80)
                        or (proporcao > 0.3 and Color3.fromRGB(255, 190, 40) or Color3.fromRGB(240, 65, 65))
                    tag.vidaTexto.Text = math.floor(vida) .. "/" .. math.floor(maxVida) .. " HP"

                    local energia, maxEnergia = lerEnergiaSpawnNew(p, p.Character)
                    if energia ~= nil then
                        tag.barraEnergia.Visible = true
                        tag.energiaTexto.Parent.Visible = true
                        tag.barraEnergia.Size = UDim2.new(math.clamp(energia / maxEnergia, 0, 1), 0, 1, 0)
                        tag.energiaTexto.Text = "ENERGIA " .. math.floor(energia) .. "/" .. math.floor(maxEnergia)
                    else
                        tag.barraEnergia.Visible = false
                        tag.energiaTexto.Parent.Visible = false
                    end
                end
            end
        end

        local function observarSpawnNew(p)
            if p == player or spawnNewConns[p] then return end
            spawnNewConns[p] = p.CharacterAdded:Connect(function()
                task.spawn(criarTagSpawnNew, p)
            end)
            if p.Character then task.spawn(criarTagSpawnNew, p) end
        end

        local function ativarSpawnNew()
            spawnNewAtivo = true
            for _, p in ipairs(PlayersService:GetPlayers()) do observarSpawnNew(p) end
            spawnNewAddedConn = PlayersService.PlayerAdded:Connect(observarSpawnNew)
            spawnNewRemovingConn = PlayersService.PlayerRemoving:Connect(function(p)
                removerTagSpawnNew(p)
                if spawnNewConns[p] then
                    spawnNewConns[p]:Disconnect()
                    spawnNewConns[p] = nil
                end
            end)
            spawnNewLoop = RunService.Heartbeat:Connect(atualizarTagsSpawnNew)
        end

        local function desativarSpawnNew()
            spawnNewAtivo = false
            if spawnNewAddedConn then spawnNewAddedConn:Disconnect(); spawnNewAddedConn = nil end
            if spawnNewRemovingConn then spawnNewRemovingConn:Disconnect(); spawnNewRemovingConn = nil end
            if spawnNewLoop then spawnNewLoop:Disconnect(); spawnNewLoop = nil end
            for _, conn in pairs(spawnNewConns) do conn:Disconnect() end
            spawnNewConns = {}
            for p in pairs(spawnNewTags) do removerTagSpawnNew(p) end
        end

        spawnNewBtn.MouseButton1Click:Connect(function()
            vibrar()
            if spawnNewAtivo then desativarSpawnNew() else ativarSpawnNew() end
            TweenService:Create(spawnNewBox, TweenInfo.new(0.15), {
                BackgroundColor3 = spawnNewAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)
            }):Play()
            if spawnNewCircle then
                TweenService:Create(spawnNewCircle, TweenInfo.new(0.15), {
                    Position = spawnNewAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)
                }):Play()
            end
        end)

        -- X-High: toggle de Raio X na aba Location.
        local molduraXHigh = criarMoldura(contLocation, 340, 85, "X-High")
        local xhighBox, xhighBtn = criarToggle(molduraXHigh)
        local xhighCircle = xhighBox:FindFirstChild("Circle")
        local xhighAtivo = false

        local function atualizarXHigh(ativo)
            xhighAtivo = ativo
            xrayEnabled = ativo
            if type(xray) == "function" then
                pcall(xray)
            end
            TweenService:Create(xhighBox, TweenInfo.new(0.15), {
                BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)
            }):Play()
            if xhighCircle then
                TweenService:Create(xhighCircle, TweenInfo.new(0.15), {
                    Position = ativo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)
                }):Play()
            end
        end

        xhighBtn.MouseButton1Click:Connect(function()
            vibrar()
            atualizarXHigh(not xhighAtivo)
        end)

        -- ESP Frozen Dimension: identifica e marca a ilha/alvo do Leviatã no mundo.
        local molduraEspFrozen = criarMoldura(contLocation, 440, 85, "ESP Frozen Dimension")
        local espFrozenBox, espFrozenBtn = criarToggle(molduraEspFrozen)
        local espFrozenCircle = espFrozenBox:FindFirstChild("Circle")
        local espFrozenAtivo = false
        local espFrozenTag = nil
        local espFrozenLoop = nil
        local espFrozenAlvo = nil
        local ultimaBuscaEspFrozen = 0

        local function normalizarNomeEspFrozen(nome)
            return string.lower(tostring(nome or "")):gsub("[%s_%-<>]", "")
        end

        local function pertenceACharacterDeJogador(obj)
            for _, jogador in ipairs(PlayersService:GetPlayers()) do
                local character = jogador.Character
                if character and obj:IsDescendantOf(character) then return true end
            end
            return false
        end

        local function parteDoAlvoFrozen(obj)
            if not obj or pertenceACharacterDeJogador(obj) then return nil end
            if obj:IsA("BasePart") then return obj end
            if obj:IsA("Model") then
                if obj:FindFirstChildOfClass("Humanoid") then return nil end
                if obj.PrimaryPart then return obj.PrimaryPart end
                return obj:FindFirstChild("HumanoidRootPart", true)
                    or obj:FindFirstChildWhichIsA("BasePart", true)
            end
            return nil
        end

        local function procurarAlvoEspFrozen()
            if espFrozenAlvo and espFrozenAlvo.Parent and espFrozenAlvo:IsDescendantOf(workspace)
                and not pertenceACharacterDeJogador(espFrozenAlvo) then
                return espFrozenAlvo
            end
            if tick() - ultimaBuscaEspFrozen < 1 then return nil end
            ultimaBuscaEspFrozen = tick()
            espFrozenAlvo = nil
            -- Só nomes de objetos do mapa/Sea Beast; não usar texto de títulos como <Frozen Dimension>.
            local prioridade = {"frozenisland", "frozendimension", "frozenwatcher", "leviathan"}
            local descendentes = workspace:GetDescendants()
            for _, chave in ipairs(prioridade) do
                for _, obj in ipairs(descendentes) do
                    if obj:IsA("Model") or obj:IsA("BasePart") then
                        local nome = normalizarNomeEspFrozen(obj.Name)
                        if nome == chave then
                            local parte = parteDoAlvoFrozen(obj)
                            if parte then espFrozenAlvo = parte; return parte end
                        end
                    end
                end
            end
            return nil
        end

        local function atualizarEspFrozen()
            local alvo = procurarAlvoEspFrozen()
            if not alvo then
                if espFrozenTag then espFrozenTag.Enabled = false end
                return
            end
            if not espFrozenTag or not espFrozenTag.Parent or espFrozenTag.Adornee ~= alvo then
                if espFrozenTag then pcall(function() espFrozenTag:Destroy() end) end
                espFrozenTag = Instance.new("BillboardGui")
                espFrozenTag.Name = "CELESTIAL_ESP_FROZEN_DIMENSION"
                espFrozenTag.Size = UDim2.new(0, 220, 0, 48)
                espFrozenTag.StudsOffset = Vector3.new(0, 5, 0)
                espFrozenTag.AlwaysOnTop = true
                espFrozenTag.ResetOnSpawn = false
                espFrozenTag.Adornee = alvo
                espFrozenTag.Parent = gui
                local label = Instance.new("TextLabel")
                label.Name = "Label"
                label.Size = UDim2.new(1, 0, 1, 0)
                label.BackgroundTransparency = 1
                label.Text = "FROZEN DIMENSION"
                label.TextColor3 = Color3.fromRGB(100, 220, 255)
                label.TextStrokeTransparency = 0
                label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                label.Font = FONTE_TEXTO
                label.TextSize = 14
                label.Parent = espFrozenTag
            end
            espFrozenTag.Enabled = true
            local char = player.Character
            local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
            local label = espFrozenTag:FindFirstChild("Label")
            if root and label then
                label.Text = "FROZEN DIMENSION\n" .. math.floor((alvo.Position - root.Position).Magnitude) .. "m"
            end
        end

        local function setEspFrozen(ativo)
            espFrozenAtivo = ativo
            TweenService:Create(espFrozenBox, TweenInfo.new(0.15), {
                BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)
            }):Play()
            if espFrozenCircle then
                TweenService:Create(espFrozenCircle, TweenInfo.new(0.15), {
                    Position = ativo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)
                }):Play()
            end
            if ativo then
                espFrozenLoop = task.spawn(function()
                    while espFrozenAtivo do
                        pcall(atualizarEspFrozen)
                        task.wait(0.5)
                    end
                end)
            else
                if espFrozenLoop then pcall(task.cancel, espFrozenLoop); espFrozenLoop = nil end
                if espFrozenTag then pcall(function() espFrozenTag:Destroy() end); espFrozenTag = nil end
                espFrozenAlvo = nil
            end
        end

        espFrozenBtn.MouseButton1Click:Connect(function()
            vibrar()
            setEspFrozen(not espFrozenAtivo)
        end)

        contLocation.CanvasSize = UDim2.new(0, 0, 0, 860)
    end
end
-- ===================== FRUTAS =====================
do
    local containerFruit = frame:FindFirstChild("ContainerAba_fruit")
    if not containerFruit then return end

 local molduraGirar = criarMoldura(containerFruit, 40, 85, "Auto Girar Fruta")
    local girarBox, girarBtn = criarToggle(molduraGirar)
    local girarCircle = girarBox:FindFirstChild("Circle")
    
    local girarAtivo = false
    local COOLDOWN_GIRO = 2 * 60 * 60
    local ARQUIVO_GIRO = "celestial_ultimo_giro.txt"
    local ultimoGiro = 0
    pcall(function() if isfile and isfile(ARQUIVO_GIRO) and readfile then ultimoGiro = tonumber(readfile(ARQUIVO_GIRO)) or 0 end end)
    local function salvarUltimoGiro() pcall(function() if writefile then writefile(ARQUIVO_GIRO, tostring(ultimoGiro)) end end) end
    local function restanteGiro() return COOLDOWN_GIRO - (os.time() - ultimoGiro) end
    local function girarUmaVez()
        if restanteGiro() > 0 then return false end
        local sucesso = pcall(function()
            ReplicatedStorage:WaitForChild("Modules", 5):WaitForChild("Net", 5):WaitForChild("RF/GachaNetworkRF", 5):InvokeServer({ Context = "Purchase", BoxName = "ZiolesGacha" })
        end)
        if sucesso then ultimoGiro = os.time(); salvarUltimoGiro(); return true end
        return false
    end
    girarBtn.MouseButton1Click:Connect(function()
        vibrar()
        girarAtivo = not girarAtivo
        TweenService:Create(girarBox, TweenInfo.new(0.15), {BackgroundColor3 = girarAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if girarCircle then TweenService:Create(girarCircle, TweenInfo.new(0.15), {Position = girarAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        if girarAtivo then
            if restanteGiro() <= 0 then girarUmaVez() end
            task.spawn(function() while girarAtivo do if restanteGiro() <= 0 then girarUmaVez() end; task.wait(1) end end)
        end
    end)

 local molduraColeta = criarMoldura(containerFruit, 140, 85, "Coletar Frutas")
    local coletaBox, coletaBtn = criarToggle(molduraColeta)
    local coletaCircle = coletaBox:FindFirstChild("Circle")
    
    local alvoDaFruta = function(obj)
        if obj:IsA("Tool") then return obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart", true)
        elseif obj:IsA("Model") then return obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
        elseif obj:IsA("BasePart") then return obj end
        return nil
    end
    local ehFrutaNoChao = function(obj)
        if not obj:IsA("Tool") then return false end
        if not obj:IsDescendantOf(workspace) then return false end
        local handle = obj:FindFirstChild("Handle")
        if not handle or not handle:IsA("BasePart") then return false end
        if string.find(obj.Name, "_", 1, true) or string.find(obj.Name, ".", 1, true) or #obj.Name > 20 then return false end
        local conhecida = (shared.CelestialNomesFrutas and shared.CelestialNomesFrutas[obj.Name]) or false
        local tooltipFruta = (obj.ToolTip == "Blox Fruit")
        local temFilhoFruit = obj:FindFirstChild("Fruit") ~= nil
        if not (conhecida or tooltipFruta or temFilhoFruit) then return false end
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            if p.Character and obj:IsDescendantOf(p.Character) then return false end
        end
        return true
    end

    local TEMPO_IGNORAR = 2
    local coletaAtivo = false
    local coletaToken = 0
    local tweenAtual = nil
    local ignoradas = {}
    local noclipConn = nil
    local colOrig = {}
    local function ligarNoclip()
        if noclipConn then return end
        noclipConn = RunService.Stepped:Connect(function()
            local char = player.Character
            if not char then return end
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then
                    if colOrig[p] == nil then colOrig[p] = p.CanCollide end
                    p.CanCollide = false
                end
            end
            local root = char:FindFirstChild("HumanoidRootPart")
            if root then root.AssemblyLinearVelocity = Vector3.zero end
        end)
    end
    local function desligarNoclip()
        if noclipConn then noclipConn:Disconnect() noclipConn = nil end
        for p, v in pairs(colOrig) do if p and p.Parent then p.CanCollide = v end end
        colOrig = {}
    end
    local function getRoot()
        local char = player.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function listarSpawnadas()
        local lista = {}
        for _, obj in ipairs(workspace:GetDescendants()) do
            if ignoradas[obj] and ignoradas[obj] <= tick() then ignoradas[obj] = nil end
            if not ignoradas[obj] then
                local ok, ehFruta = pcall(ehFrutaNoChao, obj)
                if ok and ehFruta then table.insert(lista, obj) end
            end
        end
        return lista
    end
    local function irAteFruta(obj, token)
        local root = getRoot()
        local alvo = alvoDaFruta(obj)
        if not root or not alvo then return end
        local dist = (alvo.Position - root.Position).Magnitude
        local tempo = math.max(dist / _G.FarmSpeed, 0.05)
        local tw = TweenService:Create(root, TweenInfo.new(tempo, Enum.EasingStyle.Linear), { CFrame = alvo.CFrame })
        tweenAtual = tw
        ligarNoclip()
        tw:Play()
        local inicio = tick()
        while token == coletaToken and tick() - inicio < tempo + 0.2
            and obj:IsDescendantOf(workspace) and alvo.Parent do task.wait(0.05) end
        tw:Cancel()
        if tweenAtual == tw then tweenAtual = nil end
        desligarNoclip()
        if token == coletaToken and obj:IsDescendantOf(workspace) and alvo.Parent then
            local root2 = getRoot()
            if root2 then
                root2.CFrame = alvo.CFrame
                if firetouchinterest then pcall(function()
                    firetouchinterest(root2, alvo, 0)
                    firetouchinterest(root2, alvo, 1)
                end) end
            end
        end
        if token == coletaToken then
            task.wait(0.5)
            if obj:IsDescendantOf(workspace) then ignoradas[obj] = tick() + TEMPO_IGNORAR
            else ignoradas[obj] = nil end
        end
    end
    local function loopColeta(token)
        while token == coletaToken do
            pcall(function()
                local root = getRoot()
                local lista = listarSpawnadas()
                if root and #lista > 0 then
                    local function distDe(o)
                        local al = alvoDaFruta(o)
                        return al and (al.Position - root.Position).Magnitude or math.huge
                    end
                    table.sort(lista, function(a, b) return distDe(a) < distDe(b) end)
                    irAteFruta(lista[1], token)
                end
            end)
            task.wait(0.3)
        end
    end
    coletaBtn.MouseButton1Click:Connect(function()
        vibrar()
        coletaAtivo = not coletaAtivo
        TweenService:Create(coletaBox, TweenInfo.new(0.15), {BackgroundColor3 = coletaAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if coletaCircle then TweenService:Create(coletaCircle, TweenInfo.new(0.15), {Position = coletaAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        coletaToken += 1
        if coletaAtivo then ignoradas = {}; task.spawn(loopColeta, coletaToken)
        else if tweenAtual then tweenAtual:Cancel(); tweenAtual = nil end; desligarNoclip() end
    end)

 local molduraStore = criarMoldura(containerFruit, 240, 85, "Guardar Frutas")
    local storeBox, storeBtn = criarToggle(molduraStore)
    local storeCircle = storeBox:FindFirstChild("Circle")
    
    storeBtn.MouseButton1Click:Connect(function()
        vibrar()
        _G.AutoStoreFruit = not _G.AutoStoreFruit
        TweenService:Create(storeBox, TweenInfo.new(0.15), {BackgroundColor3 = _G.AutoStoreFruit and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if storeCircle then TweenService:Create(storeCircle, TweenInfo.new(0.15), {Position = _G.AutoStoreFruit and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
    end)

 local molduraSpawnFrutas = criarMoldura(containerFruit, 340, 100, "ESP Fruits")
    local frutasBox, frutasBtn = criarToggle(molduraSpawnFrutas)
    local frutasCircle = frutasBox:FindFirstChild("Circle")
    
    local frutasStatus = Instance.new("TextLabel", molduraSpawnFrutas)
    frutasStatus.Size = UDim2.new(1, -20, 0, 18)
    frutasStatus.Position = UDim2.new(0, 10, 0, 78)
    frutasStatus.BackgroundTransparency = 1
 frutasStatus.Text = ""
 frutasStatus.TextColor3 = COR_TEXTO_SUB
    frutasStatus.Font = FONTE_TEXTO
 frutasStatus.TextSize = 11
 frutasStatus.TextXAlignment = Enum.TextXAlignment.Center

    local frutasTags = {}
    local frutasLoop = nil
    local frutasUltimoDist, frutasUltimoScan = 0, 0
    local function nomePareceFruta(nome)
        if type(nome) ~= "string" or nome == "" then return false end
        if string.find(nome, "_", 1, true) then return false end
        if string.find(nome, ".", 1, true) then return false end
        local nomeMin = string.lower(nome)
        if string.sub(nomeMin, 1, 10) == "bloxfruits" then return false end
        if #nome > 20 then return false end
        return true
    end
    local function nomeDaFruta(obj)
        local n = obj.Name
        if string.lower(n) ~= "fruit" then return n end
        for _, k in ipairs({"FruitName", "Name", "Fruit"}) do
            local at = obj:GetAttribute(k)
            if type(at) == "string" and at ~= "" then return at end
        end
        for _, c in ipairs(obj:GetDescendants()) do
            if c:IsA("StringValue") and c.Value ~= "" and (c.Name == "FruitName" or c.Name == "Name" or c.Name == "Fruit") then return c.Value end
        end
        return n
    end
    local function removerTagFruta(obj)
        local tag = frutasTags[obj]
        if tag then pcall(function() tag.bb:Destroy() end); frutasTags[obj] = nil end
    end
    local function criarTagFruta(obj)
        local alvo = alvoDaFruta(obj)
        if not alvo then return end
        local bb = Instance.new("BillboardGui")
        bb.Name = "FRUTA_ESP"
        bb.Adornee = alvo
        bb.AlwaysOnTop = true
        bb.Size = UDim2.new(0, 200, 0, 36)
        bb.StudsOffset = Vector3.new(0, 2.5, 0)
        bb.ResetOnSpawn = false
        bb.Parent = gui
        local lbl = Instance.new("TextLabel", bb)
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        local nomeFruta = nomeDaFruta(obj)
 lbl.Text = nomeFruta
 lbl.TextColor3 = Color3.fromRGB(255, 215, 0)
 lbl.TextStrokeTransparency = 0
 lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.Font = FONTE_TEXTO
 lbl.TextSize = 14
        frutasTags[obj] = { bb = bb, lbl = lbl, alvo = alvo, nome = nomeFruta }
    end
    local function escanearFrutas()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if frutasTags[obj] == nil then
                local ok, ehFruta = pcall(ehFrutaNoChao, obj)
                if ok and ehFruta then pcall(criarTagFruta, obj) end
            end
        end
        local total = 0
        for obj, tag in pairs(frutasTags) do
            if not obj:IsDescendantOf(workspace) or not tag.alvo or not tag.alvo.Parent then removerTagFruta(obj)
            else total = total + 1 end
        end
 frutasStatus.Text = total > 0 and (total .. " fruta(s)") or "Nenhuma fruta"
    end
    local function atualizarFrutas()
        local now = tick()
        if now - frutasUltimoScan >= 1 then frutasUltimoScan = now; pcall(escanearFrutas) end
        if now - frutasUltimoDist >= 0.2 then
            frutasUltimoDist = now
            local char = player.Character
            local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
            if not root then return end
            for objTag, tag in pairs(frutasTags) do
                if tag.alvo and tag.alvo.Parent then
                    if string.lower(tag.nome) == "fruit" then tag.nome = nomeDaFruta(objTag) end
 tag.lbl.Text = tag.nome .. "\n" .. math.floor((tag.alvo.Position - root.Position).Magnitude) .. "m"
                end
            end
        end
    end
    
    local function toggleFrutas()
        if frutasLoop then
            frutasLoop:Disconnect(); frutasLoop = nil
            TweenService:Create(frutasBox, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(60, 60, 70)}):Play()
            if frutasCircle then TweenService:Create(frutasCircle, TweenInfo.new(0.15), {Position = UDim2.new(0, 3, 0.5, -10)}):Play() end
            for obj in pairs(frutasTags) do removerTagFruta(obj) end
 frutasStatus.Text = ""
        else
            TweenService:Create(frutasBox, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(0, 120, 220)}):Play()
            if frutasCircle then TweenService:Create(frutasCircle, TweenInfo.new(0.15), {Position = UDim2.new(0, 25, 0.5, -10)}):Play() end
            frutasUltimoScan = 0
 frutasStatus.Text = "Procurando frutas..."
            frutasLoop = RunService.Heartbeat:Connect(function() pcall(atualizarFrutas) end)
        end
    end
    
    frutasBtn.MouseButton1Click:Connect(function()
        vibrar()
        toggleFrutas()
    end)
    
    containerFruit.CanvasSize = UDim2.new(0, 0, 0, 480)

    task.spawn(function()
