do
    local containerSeaEvent = frame:FindFirstChild("ContainerAba_seaevent")
    if not containerSeaEvent then return end
    local containerMar = containerSeaEvent

    local function modeloDoBarco(part)
        local boats = workspace:FindFirstChild("Boats")
        if not boats or not part:IsDescendantOf(boats) then return nil end
        local atual = part
        while atual.Parent and atual.Parent ~= boats do atual = atual.Parent end
        return atual
    end

    local function aplicarAltura(modelo, seat, targetY)
        if not modelo or not seat or not seat.Parent then return end
        local cf = modelo:GetPivot()
        local diff = targetY - cf.Position.Y
        if math.abs(diff) < 0.15 then return end
        local vel = seat.AssemblyLinearVelocity
        local angVel = seat.AssemblyAngularVelocity
        modelo:PivotTo(cf + Vector3.new(0, diff, 0))
        seat.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
        seat.AssemblyAngularVelocity = angVel
    end

 local molduraDono = criarMoldura(containerMar, 40, 112, "Dono do Barco")
