            local owner = boat:FindFirstChild("Owner")
            if not owner then return false end
            local v = owner.Value
            return v == p or v == p.Name or v == p.UserId
        end
        function Dono.acharSeat(p)
            if not p then return nil end
            local char = player.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if p == player then
                if hum and hum.SeatPart and hum.SeatPart:IsA("VehicleSeat") then return hum.SeatPart end
                local boats = workspace:FindFirstChild("Boats")
                if boats then
                    for _, boat in ipairs(boats:GetChildren()) do
                        if ehDonoDoBarco(boat, player) then
                            local seat = boat:FindFirstChildWhichIsA("VehicleSeat", true)
                            if seat then return seat end
                        end
                    end
                end
                return nil
            end
            local boats = workspace:FindFirstChild("Boats")
            if not boats then return nil end
            for _, boat in ipairs(boats:GetChildren()) do
                if ehDonoDoBarco(boat, p) then
                    local seat = boat:FindFirstChildWhichIsA("VehicleSeat", true)
