 barcoMsgLabel.TextXAlignment = Enum.TextXAlignment.Center
    local BARCO_MAX = 400
    local barcoValue = 0
    local barcoAtivo = false
    local barcoLoop = nil
    local origBarcoSpeed = {}
    local function acharBarcoSeat()
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and hum.SeatPart and hum.SeatPart:IsA("VehicleSeat") then return hum.SeatPart end
        local boats = workspace:FindFirstChild("Boats")
        if boats then
            for _, boat in ipairs(boats:GetChildren()) do
                local owner = boat:FindFirstChild("Owner")
                if owner then
                    local v = owner.Value
                    if v == player or v == player.Name or v == player.UserId then
                        local seat = boat:FindFirstChildWhichIsA("VehicleSeat", true)
                        if seat then return seat end
                    end
                end
            end
        end
        return nil
    end
    local function restaurarBarcos()
        for seat, vel in pairs(origBarcoSpeed) do pcall(function() if seat and seat.Parent then seat.MaxSpeed = vel end end) end
        origBarcoSpeed = {}
    end
    local function aplicarBarco()
        local seat = acharBarcoSeat()
        if seat then
            if origBarcoSpeed[seat] == nil then origBarcoSpeed[seat] = seat.MaxSpeed end
            if seat.MaxSpeed ~= barcoValue then seat.MaxSpeed = barcoValue end
        end
    end
    local function desativarBarco()
        barcoAtivo = false
        if barcoLoop then barcoLoop:Disconnect(); barcoLoop = nil end
        restaurarBarcos()
    end
    barcoOkBtn.MouseButton1Click:Connect(function()
        vibrar()
        if barcoAtivo then
            desativarBarco()
 barcoMsgLabel.TextColor3 = Color3.fromRGB(255, 80, 80)
 barcoMsgLabel.Text = "Barco normal"
            return
        end
        if not acharBarcoSeat() then
 barcoMsgLabel.TextColor3 = COR_ERRO_AZUL
 barcoMsgLabel.Text = "Compre/chame seu barco primeiro!"
            return
        end
 local v = tonumber(barcoInput.Text)
        if v and v > 0 then
