                return
            end
            barcoValue = v
            barcoAtivo = true
            aplicarBarco()
            barcoLoop = RunService.Heartbeat:Connect(aplicarBarco)
 barcoMsgLabel.TextColor3 = Color3.fromRGB(0, 220, 0)
