    -- Arraste o pop-up com mouse ou toque (celular).
    local popupDragging, popupDragInput, popupDragStart, popupStartPos
    pessoasPopup.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            popupDragging = true
            popupDragStart = input.Position
            popupStartPos = pessoasPopup.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then popupDragging = false end
            end)
        end
    end)
    pessoasPopup.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then popupDragInput = input end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if popupDragging and input == popupDragInput then
            local delta = input.Position - popupDragStart
            pessoasPopup.Position = UDim2.new(popupStartPos.X.Scale, popupStartPos.X.Offset + delta.X, popupStartPos.Y.Scale, popupStartPos.Y.Offset + delta.Y)
        end
    end)

    -- Identifica o barco do jogador mesmo quando ele está em pé.
    local function obterBarcoParaContagem()
        local boats = workspace:FindFirstChild("Boats")
        if not boats then return nil end

        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local seat = hum and hum.SeatPart
        if seat and seat:IsDescendantOf(boats) then
            local atual = seat
            while atual.Parent and atual.Parent ~= boats do atual = atual.Parent end
            return atual
        end

        -- Primeiro tenta reconhecer o barco pelo valor Owner.
        for _, boat in ipairs(boats:GetChildren()) do
            local owner = boat:FindFirstChild("Owner")
            if owner then
                local value = owner.Value
                if value == player or value == player.Name or value == player.UserId then
                    return boat
                end
            end
        end

        -- Se o jogador estiver em pé, procura o barco que contém seu personagem.
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso"))
        if root then
            for _, boat in ipairs(boats:GetChildren()) do
                local ok, cf, size = pcall(function() return boat:GetBoundingBox() end)
                if ok and cf and size then
                    local localPos = cf:PointToObjectSpace(root.Position)
                    local half = size * 0.5
                    if math.abs(localPos.X) <= half.X + 5
                        and math.abs(localPos.Y) <= half.Y + 8
                        and math.abs(localPos.Z) <= half.Z + 5 then
                        return boat
                    end
                end
            end
        end
        return nil
    end

    local function contarPessoasNoBarco()
        local modelo = obterBarcoParaContagem()
        if not modelo then return 0, 0, 0 end

        local ok, cf, size = pcall(function() return modelo:GetBoundingBox() end)
        if not ok or not cf or not size then return 0, 0, 0 end

        local total, emPe, sentado = 0, 0, 0
        local half = size * 0.5
        local margem = Vector3.new(5, 8, 5)

        for _, jogador in ipairs(PlayersService:GetPlayers()) do
            local character = jogador.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso"))
            if humanoid and root and humanoid.Health > 0 then
                local localPos = cf:PointToObjectSpace(root.Position)
                if math.abs(localPos.X) <= half.X + margem.X
                    and math.abs(localPos.Y) <= half.Y + margem.Y
                    and math.abs(localPos.Z) <= half.Z + margem.Z then
                    total = total + 1
                    if humanoid.SeatPart then
                        sentado = sentado + 1
                    else
                        emPe = emPe + 1
                    end
                end
            end
        end
        return total, emPe, sentado
    end

    local function setPessoasToggle(ativo)
        TweenService:Create(pessoasBox, TweenInfo.new(0.15), {BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if pessoasCircle then
            TweenService:Create(pessoasCircle, TweenInfo.new(0.15), {Position = ativo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play()
        end
    end

    pessoasBtn.MouseButton1Click:Connect(function()
        vibrar()
        pessoasAtivo = not pessoasAtivo
        setPessoasToggle(pessoasAtivo)
        pessoasPopup.Visible = pessoasAtivo
        if pessoasLoop then pessoasLoop:Disconnect(); pessoasLoop = nil end
        if pessoasAtivo then
            local function atualizarContagem()
                if not pessoasAtivo then return end
                local total, emPe, sentado = contarPessoasNoBarco()
                pessoasTexto.Text = "TOTAL: " .. tostring(total)
                    .. "\nEm pé: " .. tostring(emPe) .. "\nSentado: " .. tostring(sentado)
            end
            atualizarContagem()
            pessoasLoop = RunService.Heartbeat:Connect(atualizarContagem)
        end
    end)

    -- Contador local por OCORRÊNCIA marítima (não por criatura individual).
    -- Inimigos que surgem em conjunto são agrupados em uma única ocorrência.
    -- O progresso é estimado localmente; o jogo não fornece aqui um contador oficial.
    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
    do -- [CORRECAO] escopo limitado: evita estourar o limite de 200 variaveis locais
    local EVENTOS_MARITIMOS_META = 20
    local JANELA_AGRUPAMENTO = 12 -- segundos para reunir inimigos do mesmo surgimento
    local eventosMaritimosRestantes = EVENTOS_MARITIMOS_META
    local eventosMaritimosConcluidos = 0
    local eventosMaritimosConexoes = {}
    local gruposEventosMaritimos = {}
    local grupoMaritimoAtual = nil
    local pastaInimigosMar = nil

    local molduraEventos = criarMoldura(containerMar, 0, 124, "Eventos marítimos - Cooldown")
    local eventosStatus = Instance.new("TextLabel", molduraEventos)
    eventosStatus.Size = UDim2.new(1, -20, 0, 22)
    eventosStatus.Position = UDim2.new(0, 10, 0, 31)
    eventosStatus.BackgroundTransparency = 1
    eventosStatus.Text = "Cooldown: monitorando eventos marítimos"
    eventosStatus.TextColor3 = Color3.fromRGB(255, 205, 90)
    eventosStatus.Font = FONTE_TEXTO
    eventosStatus.TextSize = 11
    eventosStatus.TextXAlignment = Enum.TextXAlignment.Left

    local eventosContagem = Instance.new("TextLabel", molduraEventos)
    eventosContagem.Size = UDim2.new(1, -20, 0, 22)
    eventosContagem.Position = UDim2.new(0, 10, 0, 56)
    eventosContagem.BackgroundTransparency = 1
    eventosContagem.Text = "Faltam: 20 eventos marítimos"
    eventosContagem.TextColor3 = COR_TEXTO
    eventosContagem.Font = FONTE_TITULO
    eventosContagem.TextSize = 12
    eventosContagem.TextXAlignment = Enum.TextXAlignment.Left

    local atualizarEventosBtn = Instance.new("TextButton", molduraEventos)
    atualizarEventosBtn.Size = UDim2.new(1, -20, 0, 28)
    atualizarEventosBtn.Position = UDim2.new(0, 10, 0, 86)
    atualizarEventosBtn.BackgroundColor3 = Color3.fromRGB(0, 120, 220)
    atualizarEventosBtn.BorderSizePixel = 0
    atualizarEventosBtn.Text = "ATUALIZAR"
    atualizarEventosBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    atualizarEventosBtn.Font = FONTE_TITULO
    atualizarEventosBtn.TextSize = 10
    Instance.new("UICorner", atualizarEventosBtn).CornerRadius = UDim.new(0, 6)
    addWhiteStroke(atualizarEventosBtn)

    local function atualizarTextoEventos()
        eventosMaritimosRestantes = math.clamp(eventosMaritimosRestantes, 0, EVENTOS_MARITIMOS_META)
        if eventosMaritimosRestantes > 0 then
            eventosStatus.Text = "Cooldown: progresso local estimado"
            eventosStatus.TextColor3 = Color3.fromRGB(255, 205, 90)
            eventosContagem.Text = "Faltam: " .. tostring(eventosMaritimosRestantes) .. " eventos marítimos"
            eventosContagem.TextColor3 = COR_TEXTO
        else
            eventosStatus.Text = "Meta local concluída — confira no Spy"
            eventosStatus.TextColor3 = Color3.fromRGB(70, 230, 120)
            eventosContagem.Text = "Faltam: 0 eventos marítimos"
            eventosContagem.TextColor3 = Color3.fromRGB(70, 230, 120)
        end
    end

    local function nomeEhEventoMaritimo(nome)
        local n = string.lower(tostring(nome or "")):gsub("[%s_%-<>]", "")
        return n:find("seabeast", 1, true) ~= nil
            or n:find("terrorshark", 1, true) ~= nil
            or n:find("piranha", 1, true) ~= nil
            or n:find("shark", 1, true) ~= nil
            or n:find("piratebrigade", 1, true) ~= nil
            or n:find("grandbrigade", 1, true) ~= nil
            or n:find("pirateship", 1, true) ~= nil
            or n:find("fishboat", 1, true) ~= nil
            or n:find("enemyship", 1, true) ~= nil
    end

    local function grupoEstaDerrotado(grupo)
        if not grupo or #grupo.membros == 0 then return false end
        for _, membro in ipairs(grupo.membros) do
            if not membro.derrotado then return false end
        end
        return true
    end

    local function tentarConcluirGrupo(grupo)
        if not grupo or grupo.concluido or grupo.finalizando then return end
        if not grupoEstaDerrotado(grupo) then return end
        local espera = math.max(0, JANELA_AGRUPAMENTO - (os.clock() - grupo.ultimoSpawn))
        grupo.finalizando = true
        task.delay(espera, function()
            grupo.finalizando = false
            if grupo.concluido or not grupoEstaDerrotado(grupo) then return end
            -- Se outro inimigo entrou no mesmo intervalo, aguarda o novo fim da janela.
            local restante = JANELA_AGRUPAMENTO - (os.clock() - grupo.ultimoSpawn)
            if restante > 0 then
                tentarConcluirGrupo(grupo)
                return
            end
            grupo.concluido = true
            eventosMaritimosConcluidos = eventosMaritimosConcluidos + 1
            eventosMaritimosRestantes = math.max(0, EVENTOS_MARITIMOS_META - eventosMaritimosConcluidos)
            atualizarTextoEventos()
        end)
    end

    local function marcarMembroDerrotado(grupo, membro)
        if not grupo or not membro or membro.derrotado then return end
        membro.derrotado = true
        tentarConcluirGrupo(grupo)
    end

    local function obterGrupoParaSpawn()
        local agora = os.clock()
        if grupoMaritimoAtual and not grupoMaritimoAtual.concluido
            and (agora - grupoMaritimoAtual.ultimoSpawn) <= JANELA_AGRUPAMENTO then
            grupoMaritimoAtual.ultimoSpawn = agora
            return grupoMaritimoAtual
        end
        local grupo = { membros = {}, ultimoSpawn = agora, concluido = false, finalizando = false }
        table.insert(gruposEventosMaritimos, grupo)
        grupoMaritimoAtual = grupo
        return grupo
    end

    local function observarEventoMaritimo(modelo)
        if not modelo or not modelo:IsA("Model") or eventosMaritimosConexoes[modelo] then return end
        if not nomeEhEventoMaritimo(modelo.Name) then return end

        local grupo = obterGrupoParaSpawn()
        local membro = { modelo = modelo, derrotado = false }
        table.insert(grupo.membros, membro)
        eventosMaritimosConexoes[modelo] = { grupo = grupo, membro = membro, conexoes = {} }
        local dados = eventosMaritimosConexoes[modelo]

        local function conectarHumanoid(obj)
            if obj and obj:IsA("Humanoid") and not dados.humanoid then
                dados.humanoid = obj
                if obj.Health <= 0 then
                    marcarMembroDerrotado(grupo, membro)
                else
                    table.insert(dados.conexoes, obj.Died:Connect(function()
                        marcarMembroDerrotado(grupo, membro)
                    end))
                end
            end
        end

        local function conectarVida(obj)
            if not (obj:IsA("NumberValue") or obj:IsA("IntValue")) then return end
            local nome = string.lower(obj.Name)
            if nome ~= "health" and nome ~= "hp" and nome ~= "boathealth" then return end
            if dados[obj] then return end
            local vidaAnterior = tonumber(obj.Value) or 0
            dados[obj] = true
            table.insert(dados.conexoes, obj.Changed:Connect(function(novoValor)
                local vidaAtual = tonumber(novoValor)
                if vidaAnterior > 0 and vidaAtual and vidaAtual <= 0 then
                    marcarMembroDerrotado(grupo, membro)
                end
                vidaAnterior = vidaAtual or vidaAnterior
            end))
            if vidaAnterior <= 0 then marcarMembroDerrotado(grupo, membro) end
        end

        for _, desc in ipairs(modelo:GetDescendants()) do
            conectarHumanoid(desc)
            conectarVida(desc)
        end
        conectarHumanoid(modelo:FindFirstChildOfClass("Humanoid"))
        table.insert(dados.conexoes, modelo.DescendantAdded:Connect(function(desc)
            conectarHumanoid(desc)
            conectarVida(desc)
        end))
        table.insert(dados.conexoes, modelo.AncestryChanged:Connect(function(_, novoPai)
            if novoPai == nil then
                -- Modelos removidos após a derrota também encerram sua participação.
                marcarMembroDerrotado(grupo, membro)
            end
        end))
    end

    local function conectarPastaInimigosMar(pasta)
        if not pasta or pasta == pastaInimigosMar then return end
        pastaInimigosMar = pasta
        for _, inimigo in ipairs(pasta:GetChildren()) do
            observarEventoMaritimo(inimigo)
        end
        pasta.ChildAdded:Connect(function(inimigo)
            task.defer(function() observarEventoMaritimo(inimigo) end)
        end)
    end

    conectarPastaInimigosMar(workspace:FindFirstChild("Enemies"))
    workspace.ChildAdded:Connect(function(obj)
        if obj.Name == "Enemies" then conectarPastaInimigosMar(obj) end
    end)

    atualizarEventosBtn.MouseButton1Click:Connect(function()
        vibrar()
        atualizarTextoEventos()
        atualizarEventosBtn.Text = "ATUALIZADO"
        task.delay(1, function()
            if atualizarEventosBtn and atualizarEventosBtn.Parent then
                atualizarEventosBtn.Text = "ATUALIZAR"
            end
        end)
    end)
    atualizarTextoEventos()

    -- Leviatã: encontrar OU remover/derrotar o mesmo modelo pode disparar
    -- o reset, mas cada instância só pode iniciar um ciclo uma única vez.
    local leviataosJaProcessados = setmetatable({}, {__mode = "k"})
    local function normalizarNomeLeviata(nome)
        return string.lower(tostring(nome or "")):gsub("[%s_%-<>]", "")
    end
    local function reiniciarContadorPorLeviata(modelo)
        if not modelo or not modelo:IsA("Model") then return end
        if not string.find(normalizarNomeLeviata(modelo.Name), "leviathan", 1, true) then return end
        if leviataosJaProcessados[modelo] then return end
        leviataosJaProcessados[modelo] = true
        eventosMaritimosConcluidos = 0
        eventosMaritimosRestantes = EVENTOS_MARITIMOS_META
        atualizarTextoEventos()
    end

    -- Também verifica modelos que já existiam quando o script foi iniciado.
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("Model") and string.find(normalizarNomeLeviata(obj.Name), "leviathan", 1, true) then
            reiniciarContadorPorLeviata(obj)
        end
    end

    workspace.DescendantAdded:Connect(function(obj)
        if obj:IsA("Model") and string.find(normalizarNomeLeviata(obj.Name), "leviathan", 1, true) then
            reiniciarContadorPorLeviata(obj)
            obj.AncestryChanged:Connect(function(_, novoPai)
                if novoPai == nil then
                    -- A remoção do mesmo modelo não reinicia o contador de novo.
                    reiniciarContadorPorLeviata(obj)
                end
            end)
        end
    end)

    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
    do -- [CORRECAO] escopo limitado: evita estourar o limite de 200 variaveis locais
 local molduraRochas = criarMoldura(containerMar, 485, 85, "Remover Rochas")
    local rochaBox, rochaBtn = criarToggleDireita(molduraRochas, 22)
    local rochaCircle = rochaBox:FindFirstChild("Circle")
    local rochaAtivo = false
    local rochaLoop = nil
    local rochaPastasRemovidas = {}
    local function removerPastaRocks()
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "Rocks" then
                if not rochaPastasRemovidas[obj] then rochaPastasRemovidas[obj] = obj.Parent end
                obj.Parent = nil
            end
        end
    end
    local function restaurarPastaRocks()
        for obj, parent in pairs(rochaPastasRemovidas) do
            pcall(function() if obj and not obj.Parent then obj.Parent = parent or workspace end end)
        end
        rochaPastasRemovidas = {}
    end
    rochaBtn.MouseButton1Click:Connect(function()
        rochaAtivo = not rochaAtivo
        TweenService:Create(rochaBox, TweenInfo.new(0.15), {BackgroundColor3 = rochaAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if rochaCircle then TweenService:Create(rochaCircle, TweenInfo.new(0.15), {Position = rochaAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        vibrar()
        if rochaAtivo then
            removerPastaRocks()
            rochaLoop = task.spawn(function() while rochaAtivo do removerPastaRocks(); task.wait(0.5) end end)
        else
            if rochaLoop then task.cancel(rochaLoop); rochaLoop = nil end
            restaurarPastaRocks()
        end
    end)

    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
    do -- [CORRECAO] escopo limitado: evita estourar o limite de 200 variaveis locais
 local molduraBring = criarMoldura(containerMar, 585, 80, "Bring Boat")
    local bringBox, bringBtn = criarToggle(molduraBring)
    local bringCircle = bringBox:FindFirstChild("Circle")

    local bringMsg = Instance.new("TextLabel", molduraBring)
    bringMsg.Size = UDim2.new(1, -20, 0, 16)
    bringMsg.Position = UDim2.new(0, 10, 0, 60)
    bringMsg.BackgroundTransparency = 1
 bringMsg.Text = ""
 bringMsg.TextColor3 = COR_TEXTO
    bringMsg.Font = FONTE_TEXTO
 bringMsg.TextSize = 10
 bringMsg.TextWrapped = true
 bringMsg.TextXAlignment = Enum.TextXAlignment.Center

    local bringTentando = false
    local bringToken = 0

    local function setBringButton(ativo)
        TweenService:Create(bringBox, TweenInfo.new(0.15), {
            BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)
        }):Play()
        if bringCircle then
            TweenService:Create(bringCircle, TweenInfo.new(0.15), {
                Position = ativo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)
            }):Play()
        end
    end

    local function trazerBarco()
        if not Dono.sel or not Dono.sel.Parent then
            Dono.sel = nil
            donoBtn.Text = "Selecionar jogador ▼"
            bringMsg.TextColor3 = COR_ALERTA
            bringMsg.Text = "Selecione um jogador."
            return
        end
        bringToken = bringToken + 1
        local myToken = bringToken
        bringTentando = true
        setBringButton(true)
 bringMsg.TextColor3 = Color3.fromRGB(255, 200, 80)
 bringMsg.Text = "Procurando " .. Dono.sel.Name .. "..."
        task.spawn(function()
            local inicio = tick()
            local sentou, achou = false, false
            while bringTentando and bringToken == myToken and tick() - inicio < 5 do
                local char = player.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if hum and hum.SeatPart and hum.SeatPart:IsA("VehicleSeat") then
                    sentou = true
                    break
                end
                local seat = Dono.acharSeat(Dono.sel)
                if seat and root and hum then
                    achou = true
                    root.CFrame = seat.CFrame * CFrame.new(0, 2.5, 0)
                    pcall(function() seat:Sit(hum) end)
                end
                task.wait(0.25)
            end
            if bringToken ~= myToken then return end
            local cancelado = not bringTentando
            bringTentando = false
            if sentou then
 bringMsg.TextColor3 = Color3.fromRGB(0, 220, 0)
 bringMsg.Text = " No barco! Desativando..."
                task.wait(1)
                if bringToken ~= myToken then return end
                setBringButton(false)
 bringMsg.Text = ""
            else
                setBringButton(false)
                if cancelado then
 bringMsg.Text = ""
                elseif achou then
 bringMsg.Text = "Cheguei, mas nao sentou"
                else
 bringMsg.Text = "Barco nao encontrado!"
                end
            end
        end)
    end

    local function alternarBringBoat()
        vibrar()
        if bringTentando then
            bringTentando = false
            bringToken = bringToken + 1
            setBringButton(false)
            bringMsg.Text = ""
        else
            trazerBarco()
        end
    end

    bringBtn.MouseButton1Click:Connect(alternarBringBoat)

    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
    do -- [CORRECAO] escopo limitado: evita estourar o limite de 200 variaveis locais
 local molduraDia = criarMoldura(containerMar, 680, 85, "Sempre Dia")
    local diaBox, diaBtn = criarToggle(molduraDia)
    local diaCircle = diaBox:FindFirstChild("Circle")
    local diaAtivo = false
    local diaLoop = nil
    local estadoOriginalDia = nil
    local function salvarEstadoOriginal()
        estadoOriginalDia = {
            ClockTime = Lighting.ClockTime
        }
    end
    local function aplicarDia()
        -- Mantém apenas o horário diurno; não altera brilho, cores, sombras,
        -- atmosfera, neblina ou efeitos locais do mapa.
        Lighting.ClockTime = 14
    end
    local function restaurarDia()
        if not estadoOriginalDia then return end
        Lighting.ClockTime = estadoOriginalDia.ClockTime
        estadoOriginalDia = nil
    end
    local function toggleDia()
        diaAtivo = not diaAtivo
        TweenService:Create(diaBox, TweenInfo.new(0.15), {BackgroundColor3 = diaAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if diaCircle then TweenService:Create(diaCircle, TweenInfo.new(0.15), {Position = diaAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        vibrar()
        if diaAtivo then
            salvarEstadoOriginal()
            aplicarDia()
            diaLoop = RunService.Heartbeat:Connect(function()
                if not diaAtivo then return end
                if Lighting.ClockTime < 13 or Lighting.ClockTime > 15 then
                    Lighting.ClockTime = 14
                end
            end)
        else
            if diaLoop then diaLoop:Disconnect(); diaLoop = nil end
            restaurarDia()
        end
    end
    diaBtn.MouseButton1Click:Connect(toggleDia)
    task.spawn(function() task.wait(0.5); if not diaAtivo then toggleDia() end end)

    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
 local molduraFog = criarMoldura(containerMar, 780, 85, "Remove Fog")
    local fogBox, fogBtn = criarToggle(molduraFog)
    local fogCircle = fogBox:FindFirstChild("Circle")
    local fogAtivo = false
    local fogLoop = nil
    local fogUltimo = 0
    local fogRemovidos = {}
    local FOG_LAYERS = { "KitsuneFog", "PrehistoricFog", "rip_indra", "SeaTerrorCC" }
    local function fogRemoverObj(chave, obj)
        if fogRemovidos[chave] == nil then
            fogRemovidos[chave] = { obj = obj, parent = obj.Parent }
            obj.Parent = nil
        else obj:Destroy() end
    end
    local function aplicarFog()
        for _, v in pairs(Lighting:GetChildren()) do if v:IsA("Sky") then fogRemoverObj("Sky", v) end end
        local layers = Lighting:FindFirstChild("LightingLayers")
        if layers then
            for _, nome in ipairs(FOG_LAYERS) do
                local obj = layers:FindFirstChild(nome)
                if obj then fogRemoverObj("Layer_" .. nome, obj) end
            end
        end
    end
    local function toggleFog()
        fogAtivo = not fogAtivo
        TweenService:Create(fogBox, TweenInfo.new(0.15), {BackgroundColor3 = fogAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if fogCircle then TweenService:Create(fogCircle, TweenInfo.new(0.15), {Position = fogAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        vibrar()
        if fogAtivo then
            pcall(aplicarFog)
            fogLoop = RunService.Heartbeat:Connect(function()
                local now = tick()
                if now - fogUltimo < 0.25 then return end
                fogUltimo = now
                pcall(aplicarFog)
            end)
        else
            if fogLoop then fogLoop:Disconnect(); fogLoop = nil end
            for chave, dados in pairs(fogRemovidos) do
                pcall(function() if dados.parent and dados.parent.Parent then dados.obj.Parent = dados.parent end end)
            end
            fogRemovidos = {}
        end
    end
    fogBtn.MouseButton1Click:Connect(toggleFog)
    task.spawn(function() task.wait(0.5); if not fogAtivo then toggleFog() end end)


    -- ===================== AUTO FROZEN DIMENSION / SEA EVENTS =====================
    local function setToggleVisual(box, circle, ativo)
        TweenService:Create(box, TweenInfo.new(0.15), {BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if circle then
            TweenService:Create(circle, TweenInfo.new(0.15), {
                Position = ativo
                    and UDim2.new(0, 25, 0.5, -10)
                    or UDim2.new(0, 3, 0.5, -10)
            }):Play()
        end
    end

    local function normalizarNome(nome)
        return string.lower(tostring(nome or "")):gsub("[%s_%-<>]", "")
    end

    do -- [CORRECAO] escopo limitado: evita estourar o limite de 200 variaveis locais
    local molduraFrozen = criarMoldura(containerMar, 880, 65, "Auto Frozen Dimension")
    local frozenBox, frozenBtn = criarToggle(molduraFrozen)
    local frozenCircle = frozenBox:FindFirstChild("Circle")
    local frozenAtivo = false
    local frozenTask = nil
    local frozenGeneration = 0

    local frozenAlvoCache = nil
    local ultimaBuscaFrozen = 0
    local function procurarFrozenWatcher()
        if frozenAlvoCache and frozenAlvoCache.Parent then
            return frozenAlvoCache
        end
        if tick() - ultimaBuscaFrozen < 1.5 then
            return nil
        end
        ultimaBuscaFrozen = tick()
        frozenAlvoCache = nil
        local function isPlayerCharacterPart(obj)
            for _, jogador in ipairs(PlayersService:GetPlayers()) do
                local character = jogador.Character
                if character and obj:IsDescendantOf(character) then return true end
            end
            return false
        end
        local prioridades = {"frozenwatcher", "leviathan", "frozenisland", "frozendimension"}
        local descendentes = workspace:GetDescendants()
        for _, chave in ipairs(prioridades) do
            for _, obj in ipairs(descendentes) do
                if (obj:IsA("Model") or obj:IsA("BasePart")) and not isPlayerCharacterPart(obj) then
                    local nome = normalizarNome(obj.Name)
                    if nome == chave then
                        local part = obj:IsA("BasePart") and obj
                            or (obj.PrimaryPart
                                or obj:FindFirstChild("HumanoidRootPart", true)
                                or obj:FindFirstChildWhichIsA("BasePart", true))
                        if part and not isPlayerCharacterPart(part) then
                            frozenAlvoCache = part
                            return part
                        end
                    end
                end
            end
        end
        return nil
    end

    local function obterBarcoLocal()
        local boats = workspace:FindFirstChild("Boats")
        if not boats then return nil, nil end
        local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        local seat = hum and hum.SeatPart
        if seat and seat:IsA("VehicleSeat") and seat:IsDescendantOf(boats) then
            local model = seat
            while model.Parent and model.Parent ~= boats do model = model.Parent end
            return model, seat
        end
        local seatDono = Dono.acharSeat(player)
        if seatDono and seatDono:IsDescendantOf(boats) then
            local model = seatDono
            while model.Parent and model.Parent ~= boats do model = model.Parent end
            return model, seatDono
        end
        return nil, nil
    end

    local function loopFrozenDimension(token)
        while frozenAtivo and frozenGeneration == token do
            local ok, erro = pcall(function()
                if game.PlaceId ~= 7449423635 then
                    task.wait(1)
                    return
                end

                local barco, seat = obterBarcoLocal()
                if not barco or not seat then
                    task.wait(1)
                    return
                end

                local alvo = procurarFrozenWatcher()
                if alvo then
                    local delta = alvo.Position - seat.Position
                    local distancia = delta.Magnitude
                    if distancia > 70 then
                        -- Avança em linha reta: não aplica direção lateral.
                        seat.Steer = 0
                        seat.Throttle = 1
                    else
                        seat.Throttle = 0
                        seat.Steer = 0
                    end
                else
                    -- O evento só aparece no Danger Level 6; mantém o barco avançando
                    -- na direção atual para procurar enquanto o jogador já está nessa área.
                    seat.Throttle = 1
                    seat.Steer = 0
                end
            end)

            if not ok then
                warn("[Auto Frozen Dimension] " .. tostring(erro))
            end
            task.wait(0.35)
        end

        local _, seat = obterBarcoLocal()
        if seat then
            pcall(function() seat.Throttle = 0; seat.Steer = 0 end)
        end
    end

    frozenBtn.MouseButton1Click:Connect(function()
        vibrar()
        frozenAtivo = not frozenAtivo
        setToggleVisual(frozenBox, frozenCircle, frozenAtivo)
        frozenGeneration = frozenGeneration + 1
        if frozenAtivo then
            local token = frozenGeneration
            frozenTask = task.spawn(loopFrozenDimension, token)
        else
            local _, seat = obterBarcoLocal()
            if seat then pcall(function() seat.Throttle = 0; seat.Steer = 0 end) end
            if frozenTask then pcall(task.cancel, frozenTask); frozenTask = nil end
        end
    end)
    -- ===================== FIM AUTO FROZEN DIMENSION / SEA EVENTS =====================

    containerSeaEvent.CanvasSize = UDim2.new(0, 0, 0, 1117)
    end -- [CORRECAO] fim do escopo limitado (libera variaveis locais)
end
