                if velCircle then TweenService:Create(velCircle, TweenInfo.new(0.15), {Position = UDim2.new(0, 3, 0.5, -10)}):Play() end
 velMsgLabel.TextColor3 = COR_ERRO_AZUL
 velMsgLabel.Text = "Digite uma velocidade válida primeiro!"
                return
            end
            local hum = getHum()
