                        end
                    end)
                end
            end))

            task.spawn(function()
                while lavaAtivo and lavaMonitorToken == tokenAtual do
                    task.wait(5)
                    if lavaAtivo and lavaMonitorToken == tokenAtual then
                        procurarLava()
                    end
                end
            end)
        else
            restaurarLava()
        end
    end)

