    local function atualizarLista(filtro)
        for _, c in ipairs(listaFrame:GetChildren()) do
            if c:IsA("TextButton") then c:Destroy() end
        end

        filtro = string.lower(filtro or "")
        for i, nome in ipairs(armasList) do
