    -- FUNÇÃO DE ATAQUE
    local AttackNoCoolDown = function(filtroAlvo)
        local Character = player.Character
        if not Character then return end
        local Tool = Character:FindFirstChildOfClass("Tool")
        if not Tool then return end
        local Hum = Character:FindFirstChildOfClass("Humanoid")
        if not Hum then return end
        if Hum.WalkSpeed == 0 then Hum.WalkSpeed = 16 end
        local enemies = workspace:FindFirstChild("Enemies")
        if not enemies then return end
        local target = nil
        local shortest = math.huge
        for _, v1 in ipairs(enemies:GetChildren()) do
            local Humanoid = v1:FindFirstChild("Humanoid")
            local HumanoidRootPart = v1:FindFirstChild("HumanoidRootPart")
            if Humanoid and HumanoidRootPart and Humanoid.Health > 0
                and (not filtroAlvo or filtroAlvo(v1)) then
                local charRoot = Character:FindFirstChild("HumanoidRootPart")
                if not charRoot then return end
                local dist = (HumanoidRootPart.Position - charRoot.Position).Magnitude
                if dist <= 60 and dist < shortest then shortest = dist; target = v1 end
            end
        end
        if not target then return end
        local targetPart = target:FindFirstChild("Head") or target:FindFirstChild("HumanoidRootPart")
        local targetRoot = target:FindFirstChild("HumanoidRootPart")
        local ReplicatedStorage4 = game:GetService("ReplicatedStorage")
        local Modules = ReplicatedStorage4:FindFirstChild("Modules")
        local net = Modules and Modules:FindFirstChild("Net")
        Tool.Enabled = true 
        if Tool:GetAttribute("WeaponType") == "Melee" or Tool:GetAttribute("WeaponType") == "Sword" or Tool.ToolTip == "Sword" or Tool.ToolTip == "Melee" then
            local t59 = {}
            for _, v2 in ipairs(target:GetChildren()) do if v2:IsA("BasePart") then table.insert(t59, {target, v2}) end end
            if #t59 > 0 and net then
                local ok_seed, response = pcall(function() return net.seed:InvokeServer() end)
                if not ok_seed then return end
                local reRegisterHit = net:FindFirstChild("RE/RegisterHit")
                local reRegisterAttack = net:FindFirstChild("RE/RegisterAttack")
                if reRegisterHit and reRegisterAttack and targetPart then
                    reRegisterAttack:FireServer()
                    pcall(function() Tool:Activate() end)
                    reRegisterHit:FireServer(targetPart, t59, {})
                    local u1599, attribute
                    for _, v1 in ipairs({ReplicatedStorage4.Util, ReplicatedStorage4.Common, ReplicatedStorage4.Remotes, ReplicatedStorage4.Assets, ReplicatedStorage4.FX}) do
                        for _, child in ipairs(v1:GetChildren()) do
                            if child:IsA("RemoteEvent") and child:GetAttribute("Id") then u1599 = child; attribute = child:GetAttribute("Id") end
                        end
                    end
                    if u1599 and attribute then
                        local v1623 = math.floor(workspace:GetServerTimeNow() / 10 % 10) + 1
                        local RegisterHit = string.gsub("RE/RegisterHit", ".", function(p369) return string.char(bit32.bxor(string.byte(p369), v1623)) end)
                        local v1625 = bit32.bxor(attribute + 909090, response * 2)
                        pcall(function() cloneref(u1599):FireServer(RegisterHit, v1625, targetPart, t59) end)
                    end
                end
            end
        elseif Tool.ToolTip == "Blox Fruit" or Tool:GetAttribute("WeaponType") == "Blox Fruit" then
            local LeftClickRemote = Tool:FindFirstChild("LeftClickRemote")
            if LeftClickRemote and targetPart then
                pcall(function() LeftClickRemote:FireServer(Vector3.new(0.01, -500, 0.01), 1, true); LeftClickRemote:FireServer(false) end)
            end
        elseif Tool.ToolTip == "Gun" or Tool:GetAttribute("WeaponType") == "Gun" then
            local REShootGunEvent = net and net:FindFirstChild("RE/ShootGunEvent")
            local vim1 = game:GetService("VirtualInputManager")
            if REShootGunEvent and targetRoot then
                pcall(function() REShootGunEvent:FireServer(targetRoot.Position, {targetRoot}) end)
                pcall(function() Tool:Activate() end)
                pcall(function() vim1:SendMouseButtonEvent(0, 0, 0, true, game, 1); task.wait(0.01); vim1:SendMouseButtonEvent(0, 0, 0, false, game, 1) end)
            end
        end
        Tool.Enabled = false 
    end

    -- KILL AURA
 local molduraAura = criarMoldura(contMulti, 0, 60, "Kill Aura (Anda Normal)")
    local auraBox, auraBtn = criarToggle(molduraAura)
    local auraCircle = auraBox:FindFirstChild("Circle")
    auraAtivo = false 
    local auraLoop = nil
    auraBtn.MouseButton1Click:Connect(function()
        if flyAtivo then vibrar(); return end
        vibrar()
        auraAtivo = not auraAtivo
        TweenService:Create(auraBox, TweenInfo.new(0.15), {BackgroundColor3 = auraAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if auraCircle then TweenService:Create(auraCircle, TweenInfo.new(0.15), {Position = auraAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        if auraAtivo then
            auraLoop = task.spawn(function()
                while auraAtivo do
                    pcall(function()
                        if not _G.TipoArma then return end
                        local char = player.Character
                        local hum = char and char:FindFirstChildOfClass("Humanoid")
                        if not char or not hum then return end

                        local currentTool = char:FindFirstChildOfClass("Tool")
                        if not currentTool or currentTool.ToolTip ~= _G.TipoArma then
                            for _, tool in ipairs(player.Backpack:GetChildren()) do
                                if tool:IsA("Tool") and tool.ToolTip == _G.TipoArma then
                                    hum:EquipTool(tool)
                                    break
                                end
                            end
                        end

                        -- Busca novamente depois do EquipTool para não usar a referência antiga.
                        currentTool = char:FindFirstChildOfClass("Tool")
                        if currentTool then currentTool.Enabled = false end
                        AttackNoCoolDown()
                    end)
                    task.wait(0.1)
                end
            end)
        else
            if auraLoop then task.cancel(auraLoop); auraLoop = nil end
            local char = player.Character
            if char then local currentTool = char:FindFirstChildOfClass("Tool") if currentTool then currentTool.Enabled = true end end
        end
    end)

