    -- FLY LOGIC (adaptado do Infinite Yield; mantém o botão original)
    local flyConnection = nil
    local flyBodyVelocity = nil
    local flyBodyGyro = nil
    local flySound = nil
    local flyVertical = 0
    local flyInputBegan, flyInputEnded

    local function pararFly()
        if flyConnection then flyConnection:Disconnect(); flyConnection = nil end
        if flyInputBegan then flyInputBegan:Disconnect(); flyInputBegan = nil end
        if flyInputEnded then flyInputEnded:Disconnect(); flyInputEnded = nil end
        if flyBodyVelocity then flyBodyVelocity:Destroy(); flyBodyVelocity = nil end
        if flyBodyGyro then flyBodyGyro:Destroy(); flyBodyGyro = nil end
        if flySound then flySound:Destroy(); flySound = nil end
        flyVertical = 0
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.PlatformStand = false end) end
        pcall(function() workspace.CurrentCamera.CameraType = Enum.CameraType.Custom end)
    end

    local function iniciarFly()
        pararFly()
        local char = player.Character or player.CharacterAdded:Wait()
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        hum.PlatformStand = true
        local controlModule = nil
        pcall(function()
            local playerScripts = player:WaitForChild("PlayerScripts")
            local playerModule = playerScripts:WaitForChild("PlayerModule")
            controlModule = require(playerModule:WaitForChild("ControlModule"))
        end)
        flySound = Instance.new("Sound")
        flySound.Name = "CelestialFlySound"
        flySound.SoundId = "rbxassetid://138186576"
        flySound.Looped = true
        flySound.Volume = 0.35
        flySound.Parent = hrp
        pcall(function() flySound:Play() end)

        local bv = Instance.new("BodyVelocity")
        bv.Name = "CelestialFlyVelocity"
        bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        bv.Velocity = Vector3.zero
        bv.Parent = hrp
        flyBodyVelocity = bv

        local bg = Instance.new("BodyGyro")
        bg.Name = "CelestialFlyGyro"
        bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        bg.P = 9e4
        bg.D = 500
        bg.CFrame = hrp.CFrame
        bg.Parent = hrp
        flyBodyGyro = bg

        flyInputBegan = UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.KeyCode == Enum.KeyCode.E then flyVertical = 1
            elseif input.KeyCode == Enum.KeyCode.Q then flyVertical = -1 end
        end)
        flyInputEnded = UserInputService.InputEnded:Connect(function(input)
            if input.KeyCode == Enum.KeyCode.E or input.KeyCode == Enum.KeyCode.Q then flyVertical = 0 end
        end)

        flyConnection = RunService.RenderStepped:Connect(function()
            local currentChar = player.Character
            local currentRoot = currentChar and currentChar:FindFirstChild("HumanoidRootPart")
            local currentHum = currentChar and currentChar:FindFirstChildOfClass("Humanoid")
            local camera = workspace.CurrentCamera
            if not currentRoot or not currentHum or not camera or not flyBodyVelocity or not flyBodyGyro then
                return
            end
            local move = Vector3.zero
            if controlModule then
                pcall(function() move = controlModule:GetMoveVector() end)
            end
            if move.Magnitude <= 0.01 then move = currentHum.MoveDirection end
            local speed = math.clamp(tonumber(_G.FlySpeed) or 50, 1, 300)
            local velocity = Vector3.zero
            if move.Magnitude > 0.01 then
                velocity = (camera.CFrame.RightVector * move.X - camera.CFrame.LookVector * move.Z) * speed
            end
            velocity += Vector3.new(0, flyVertical * speed, 0)
            flyBodyVelocity.Velocity = velocity
            flyBodyGyro.CFrame = camera.CFrame
        end)
    end

    local function alternarFlyAC()
        if auraAtivo then vibrar(); return end
        vibrar()
        flyAtivo = not flyAtivo
        TweenService:Create(flyBox, TweenInfo.new(0.15), {BackgroundColor3 = flyAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if flyCircle then TweenService:Create(flyCircle, TweenInfo.new(0.15), {Position = flyAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        if flyAtivo then iniciarFly() else pararFly() end
    end
    _G.ACHubToggleFly = alternarFlyAC
    flyBtn.MouseButton1Click:Connect(alternarFlyAC)
    
    player.CharacterAdded:Connect(function() if flyAtivo then task.wait(0.5); iniciarFly() end end)

    puloBtn.MouseButton1Click:Connect(function()
        vibrar()
        puloAtivo = not puloAtivo
        TweenService:Create(puloBox, TweenInfo.new(0.15), {BackgroundColor3 = puloAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if puloCircle then TweenService:Create(puloCircle, TweenInfo.new(0.15), {Position = puloAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play() end
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if puloAtivo then if hum then hum.JumpPower = 300 end else if hum then hum.JumpPower = 50 end end
    end)
    end
end

-- ===================== RAID (AUTO RAID) =====================
do
    local contRaid = frame:FindFirstChild("ContainerAba_raid")
    if not contRaid then return end

    local getRoot = function()
        local char = player.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    local function tweenTo(cf)
        local root = getRoot()
        if not root or not cf then return end
        local dist = (cf.Position - root.Position).Magnitude
        local tempo = math.max(dist / _G.FarmSpeed, 0.05)
        local tw = TweenService:Create(root, TweenInfo.new(tempo, Enum.EasingStyle.Linear), { CFrame = cf })
        tw:Play()
        tw.Completed:Wait()
    end

    local function inRaid()
        local main = player.PlayerGui:FindFirstChild("Main")
        if not main then return false end
        local topHud = main:FindFirstChild("TopHUDList")
        if not topHud then return false end
        local raidTimer = topHud:FindFirstChild("RaidTimer")
        return raidTimer and raidTimer.Visible == true
    end

    local function atacarMob(mob)
        local char = player.Character
        if not char then return end
        local tool = char:FindFirstChildOfClass("Tool")
        if tool then pcall(function() tool:Activate() end) end
        local targetPart = mob:FindFirstChild("Head") or mob:FindFirstChild("HumanoidRootPart")
        local root = getRoot()
        if root and targetPart and firetouchinterest then
            pcall(function()
                firetouchinterest(root, targetPart, 0)
                firetouchinterest(root, targetPart, 1)
            end)
        end
    end

    local autoRaidAtivo = false
    local autoRaidTask = nil

    local function loopAutoRaid()
        local ilhas = {"Island 1", "Island 2", "Island 3", "Island 4", "Island 5"}
        local ilhaIndex = 1
        local ilhaVisitada = false
        local alvoAtual = nil

        while autoRaidAtivo do
            pcall(function()
                local char = player.Character
                local root = getRoot()
                if not char or not root then
                    task.wait(0.5)
                    return
                end

                if not inRaid() then
                    alvoAtual = nil
                    ilhaIndex = 1
                    ilhaVisitada = false

                    local backpack = player:FindFirstChild("Backpack")
                    local temChip = (backpack and backpack:FindFirstChild("Special Microchip"))
                        or char:FindFirstChild("Special Microchip")

                    if temChip then
                        if game.PlaceId == 4442272183 or game.PlaceId == 79091703265657 then
                            tweenTo(CFrame.new(-6438.73535, 250.645355, -4501.50684))
                            task.wait(1)
                            pcall(function()
                                fireclickdetector(workspace.Map.CircleIsland.RaidSummon2.Button.Main.ClickDetector)
                            end)
                        elseif game.PlaceId == 7449423635 or game.PlaceId == 100117331123089 then
                            tweenTo(CFrame.new(-5046, 314, -2960))
                            task.wait(1.5)
                            pcall(function()
                                local main = workspace.Map["Boat Castle"].RaidSummon2.Button.Main
                                if main and main:FindFirstChild("ClickDetector") then
                                    fireclickdetector(main.ClickDetector)
                                end
                            end)
                        end
                        task.wait(5)
                    else
                        task.wait(3)
                    end
                    return
                end

                local enemiesFolder = workspace:FindFirstChild("Enemies")
                local alvoValido = alvoAtual
                    and alvoAtual.Parent == enemiesFolder
                    and alvoAtual:FindFirstChildOfClass("Humanoid")
                    and alvoAtual:FindFirstChildOfClass("Humanoid").Health > 0
                    and alvoAtual:FindFirstChild("HumanoidRootPart")

                if not alvoValido then
                    alvoAtual = nil
                    local menorDistancia = math.huge

                    if enemiesFolder then
                        for _, mob in ipairs(enemiesFolder:GetChildren()) do
                            local hum = mob:FindFirstChildOfClass("Humanoid")
                            local mobRoot = mob:FindFirstChild("HumanoidRootPart")

                            if hum and hum.Health > 0 and mobRoot then
                                local distancia = (mobRoot.Position - root.Position).Magnitude
                                if distancia < menorDistancia then
                                    menorDistancia = distancia
                                    alvoAtual = mob
                                end
                            end
                        end
                    end
                end

                if alvoAtual then
                    local mobRoot = alvoAtual:FindFirstChild("HumanoidRootPart")
                    local hum = alvoAtual:FindFirstChildOfClass("Humanoid")

                    if mobRoot and hum and hum.Health > 0 then
                        local distancia = (mobRoot.Position - root.Position).Magnitude
                        if distancia > 30 then
                            tweenTo(mobRoot.CFrame * CFrame.new(0, 10, 0))
                        end

                        atacarMob(alvoAtual)
                        task.wait(0.15)
                    else
                        alvoAtual = nil
                    end
                else
                    -- Só avança para a próxima ilha depois de limpar a atual.
                    -- Cada ilha é visitada uma única vez, evitando voltar às anteriores.
                    if ilhaIndex <= #ilhas then
                        local locations = workspace:FindFirstChild("_WorldOrigin")
                        locations = locations and locations:FindFirstChild("Locations")
                        local ilha = locations and locations:FindFirstChild(ilhas[ilhaIndex])

                        if ilha and not ilhaVisitada then
                            tweenTo(ilha.CFrame * CFrame.new(0, 30, 0))
                            ilhaVisitada = true
                            task.wait(5)
                        elseif ilhaVisitada then
                            ilhaIndex = ilhaIndex + 1
                            ilhaVisitada = false
                            task.wait(0.5)
                        else
                            -- Se o marcador ainda não carregou, aguarda sem reiniciar a rota.
                            task.wait(1)
                        end
                    else
                        task.wait(1)
                    end
                end
            end)

            task.wait(0.1)
        end
    end

 local molduraAutoRaid = criarMoldura(contRaid, 40, 110, "Auto Raid Completo")
    local raidBox, raidBtn = criarToggle(molduraAutoRaid)
    local raidCircle = raidBox:FindFirstChild("Circle")

    local raidStatus = Instance.new("TextLabel", molduraAutoRaid)
    raidStatus.Size = UDim2.new(1, -20, 0, 40)
    raidStatus.Position = UDim2.new(0, 10, 0, 58)
    raidStatus.BackgroundTransparency = 1
 raidStatus.Text = "Desativado"
 raidStatus.TextColor3 = COR_TEXTO_SUB
    raidStatus.Font = FONTE_TEXTO
 raidStatus.TextSize = 11
 raidStatus.TextWrapped = true
 raidStatus.TextXAlignment = Enum.TextXAlignment.Center

    raidBtn.MouseButton1Click:Connect(function()
        vibrar()
        autoRaidAtivo = not autoRaidAtivo

        TweenService:Create(raidBox, TweenInfo.new(0.15), {BackgroundColor3 = autoRaidAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
        if raidCircle then
            TweenService:Create(raidCircle, TweenInfo.new(0.15), {Position = autoRaidAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play()
        end

        if autoRaidAtivo then
 raidStatus.TextColor3 = COR_BOLINHA_VERDE
 raidStatus.Text = "Procurando Raid..."
            autoRaidTask = task.spawn(loopAutoRaid)
        else
 raidStatus.TextColor3 = COR_TEXTO_SUB
 raidStatus.Text = "Desativado"
            if autoRaidTask then
                pcall(function() task.cancel(autoRaidTask) end)
                autoRaidTask = nil
            end
        end
    end)

    task.spawn(function()
        while gui.Parent do
            task.wait(1)
            if autoRaidAtivo then
                if inRaid() then
 raidStatus.TextColor3 = COR_BOLINHA_VERDE
 raidStatus.Text = "Dentro da Raid "
                else
 raidStatus.TextColor3 = COR_ALERTA
 raidStatus.Text = "Sem Chip ou Fora da Raid"
