    local function atualizarListaRaids(filtro)
        for _, filho in ipairs(raidListaFrame:GetChildren()) do
            if filho:IsA("TextButton") then
                filho:Destroy()
            end
        end

        filtro = string.lower(filtro or "")
        for _, nomeRaid in ipairs(raidsDisponiveis) do
            if string.find(string.lower(nomeRaid), filtro, 1, true) then
                local itemRaid = Instance.new("TextButton", raidListaFrame)
                itemRaid.Size = UDim2.new(1, 0, 0, 30)
                itemRaid.BackgroundColor3 = Color3.fromRGB(60, 40, 80)
                itemRaid.Text = nomeRaid
                itemRaid.TextColor3 = COR_TEXTO
                itemRaid.Font = FONTE_TEXTO
                itemRaid.TextSize = 12
                itemRaid.TextXAlignment = Enum.TextXAlignment.Left
                itemRaid.ZIndex = 10001
                Instance.new("UIPadding", itemRaid).PaddingLeft = UDim.new(0, 8)
                Instance.new("UICorner", itemRaid).CornerRadius = UDim.new(0, 4)

                itemRaid.MouseButton1Click:Connect(function()
                    vibrar()
                    raidSelecionada = nomeRaid
                    raidBtn.Text = nomeRaid .. " ▼"
                    raidDropdown.Visible = false
                    raidSearch.Text = ""
                    atualizarListaRaids("")
                end)
            end
        end
    end

    raidBtn.MouseButton1Click:Connect(function()
        vibrar()
        raidDropdown.Visible = not raidDropdown.Visible
        if raidDropdown.Visible then
            atualizarListaRaids("")
        end
    end)

    raidSearch:GetPropertyChangedSignal("Text"):Connect(function()
        atualizarListaRaids(raidSearch.Text)
    end)

    voltarRaidBtn.MouseButton1Click:Connect(function()
        vibrar()
