    microchipStatus.Size = UDim2.new(1, -20, 0, 32)
    microchipStatus.Position = UDim2.new(0, 10, 0, 152)
    microchipStatus.BackgroundTransparency = 1
    microchipStatus.Text = "Selecione a raid e clique para comprar."
    microchipStatus.TextColor3 = COR_TEXTO_SUB
    microchipStatus.Font = FONTE_TEXTO
    microchipStatus.TextSize = 10
    microchipStatus.TextWrapped = true
    microchipStatus.TextXAlignment = Enum.TextXAlignment.Center

    atualizarRaidBtn.MouseButton1Click:Connect(function()
        vibrar()
