        microchipStatus.TextColor3 = COR_TEXTO_SUB
        microchipStatus.Text = "Selecione uma nova raid para comprar."
    end)

    local function encontrarMicrochip()
        local backpack = player:FindFirstChild("Backpack")
        local char = player.Character
        return (backpack and backpack:FindFirstChild("Special Microchip"))
            or (char and char:FindFirstChild("Special Microchip"))
    end

    -- Valores de compra das frutas em Beli. Para Phoenix e Dough, o jogo
    -- exige uma fruta física com valor ACIMA de 1.000.000 (ou 1.000 Fragmentos).
    local valoresFrutasRaid = {
        Rocket = 5000, Spin = 7500, Blade = 30000, Spring = 60000,
        Bomb = 80000, Smoke = 100000, Spike = 180000, Flame = 250000,
        Falcon = 300000, Ice = 350000, Sand = 420000, Dark = 500000,
        Diamond = 600000, Light = 650000, Rubber = 750000, Barrier = 800000,
        Ghost = 800000, Magma = 960000, Quake = 1000000, Buddha = 1200000,
        Love = 1300000, Spider = 1500000, Sound = 1700000, Phoenix = 1800000,
        Portal = 1900000, Rumble = 2100000, Pain = 2300000, Blizzard = 2400000,
        Gravity = 2500000, Mammoth = 2700000, ["T-Rex"] = 2700000, Dough = 2800000,
        Shadow = 2900000, Venom = 3000000, Control = 3200000, Spirit = 3400000,
        Dragon = 3500000, Leopard = 5000000, Kitsune = 8000000
    }

    local function encontrarFrutaFisica()
        -- Considera somente Tools na barra (Backpack do Roblox) ou equipada
        -- no personagem. Não consulta o inventário de frutas armazenadas.
        local containers = {player:FindFirstChild("Backpack"), player.Character}
        local primeiraFrutaNome, primeiraFrutaValor = nil, nil
        for _, container in ipairs(containers) do
            if container then
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") and (item.ToolTip == "Blox Fruit" or item:FindFirstChild("EatRemote", true)) then
                        local nomeOriginal = item:GetAttribute("OriginalName") or item.Name
                        local nomeLower = string.lower(tostring(nomeOriginal))
                        local identificada = false
                        for nomeFruta, valor in pairs(valoresFrutasRaid) do
                            if string.find(nomeLower, string.lower(nomeFruta), 1, true) then
                                identificada = true
                                if not primeiraFrutaNome then
                                    primeiraFrutaNome, primeiraFrutaValor = nomeFruta, valor
                                end
                                -- Prioriza encontrar uma fruta que realmente sirva
                                -- para Phoenix/Dough, mesmo que haja fruta barata antes.
                                if valor > 1000000 then return nomeFruta, valor end
                                break
                            end
                        end
                        if not identificada and not primeiraFrutaNome then
                            primeiraFrutaNome, primeiraFrutaValor = tostring(nomeOriginal), nil
                        end
                    end
                end
            end
        end
        return primeiraFrutaNome, primeiraFrutaValor
    end

    local function quantidadeFragmentos()
        local data = player:FindFirstChild("Data")
        local fragments = data and data:FindFirstChild("Fragments")
        return fragments and tonumber(fragments.Value) or 0
    end

    local compraEmAndamento = false
    comprarMicrochipBtn.MouseButton1Click:Connect(function()
        vibrar()
        if compraEmAndamento then return end

        if not raidSelecionada then
            microchipStatus.TextColor3 = COR_ALERTA
            microchipStatus.Text = "Clique em Selecionar Raid e escolha uma raid primeiro."
            return
        end

        if encontrarMicrochip() then
            microchipStatus.TextColor3 = COR_ALERTA
            microchipStatus.Text = "Você já possui um Special Microchip."
            return
        end

        local commF = ReplicatedStorage:FindFirstChild("Remotes")
        commF = commF and commF:FindFirstChild("CommF_")
        if not commF then
            microchipStatus.TextColor3 = COR_ALERTA
            microchipStatus.Text = "Remote de compra não encontrado."
            return
        end

        compraEmAndamento = true
        comprarMicrochipBtn.Active = false
        comprarMicrochipBtn.AutoButtonColor = false
        comprarMicrochipBtn.Text = "Comprando..."
        microchipStatus.TextColor3 = COR_TEXTO_SUB
        microchipStatus.Text = "Solicitando " .. raidSelecionada .. "..."

        task.spawn(function()
            local raidAvancada = (raidSelecionada == "Phoenix" or raidSelecionada == "Dough")
            local frutaNome, frutaValor = encontrarFrutaFisica()
            local fragmentos = quantidadeFragmentos()
            local frutaDisponivel = frutaNome ~= nil

            -- Phoenix e Dough são raids avançadas: não podem usar Beli nem
            -- frutas baratas. Exige 1.000 Fragmentos ou fruta física > 1M.
            if raidAvancada and fragmentos < 1000 and (not frutaDisponivel or not frutaValor or frutaValor <= 1000000) then
                microchipStatus.TextColor3 = COR_ALERTA
                if frutaDisponivel and frutaValor then
                    microchipStatus.Text = "Raid " .. raidSelecionada .. ": precisa de 1.000 Fragmentos ou fruta acima de 1M. Sua " .. frutaNome .. " não serve."
                elseif frutaDisponivel then
                    microchipStatus.Text = "Não foi possível confirmar o valor da fruta " .. frutaNome .. ". Para evitar consumo errado, compra cancelada."
                else
                    microchipStatus.Text = "Raid " .. raidSelecionada .. ": precisa de 1.000 Fragmentos ou fruta física acima de 1M na barra."
                end
                comprarMicrochipBtn.Text = "Comprar Microchip"
                comprarMicrochipBtn.Active = true
                comprarMicrochipBtn.AutoButtonColor = true
                compraEmAndamento = false
                return
            end

            microchipStatus.Text = raidAvancada
                and (fragmentos >= 1000 and "Solicitando chip avançado com Fragmentos..." or "Solicitando chip avançado com fruta " .. tostring(frutaNome) .. "...")
                or "Solicitando " .. raidSelecionada .. "..."

            local ok, resposta = pcall(function()
                -- Check prepara/consulta o diálogo do NPC; Select solicita o chip escolhido.
                pcall(function() commF:InvokeServer("RaidsNpc", "Check") end)
                task.wait(0.15)
                return commF:InvokeServer("RaidsNpc", "Select", raidSelecionada)
            end)

            local prazoVerificacao = os.clock() + 1.5
            while not encontrarMicrochip() and os.clock() < prazoVerificacao do
                task.wait(0.2)
            end
            if encontrarMicrochip() then
                microchipStatus.TextColor3 = COR_BOLINHA_VERDE
                microchipStatus.Text = "Microchip " .. raidSelecionada .. " obtido!"
            elseif not ok then
                microchipStatus.TextColor3 = COR_ALERTA
                microchipStatus.Text = "Falha ao solicitar a compra. Tente novamente."
            elseif type(resposta) == "string" and resposta ~= "" then
                microchipStatus.TextColor3 = COR_ALERTA
                microchipStatus.Text = resposta
            elseif raidAvancada and fragmentos >= 1000 then
                microchipStatus.TextColor3 = COR_TEXTO_SUB
                microchipStatus.Text = "Solicitação enviada. Confira o saldo de Fragmentos e o cooldown de 2 horas."
            elseif raidAvancada and frutaDisponivel then
                microchipStatus.TextColor3 = COR_TEXTO_SUB
                microchipStatus.Text = "Solicitação enviada com fruta elegível (" .. tostring(frutaNome) .. "). Confira se foi consumida."
            elseif frutaDisponivel then
                microchipStatus.TextColor3 = COR_TEXTO_SUB
                microchipStatus.Text = "Solicitação enviada. Confira se a fruta foi usada."
            else
                microchipStatus.TextColor3 = COR_TEXTO_SUB
                microchipStatus.Text = "Solicitação enviada. Confira saldo e cooldown."
            end

            comprarMicrochipBtn.Text = "Comprar Microchip"
            comprarMicrochipBtn.Active = true
            comprarMicrochipBtn.AutoButtonColor = true
            compraEmAndamento = false
        end)
    end)
    -- ===================== FIM AUTO COMPRAR MICROCHIP =====================

    contRaid.CanvasSize = UDim2.new(0, 0, 0, 390)
end
-- ===================== FIM AUTO RAID =====================
-- ===================== PVP (TELEPORT PLAYER) =====================
do
