        tpAtualizarBtn.ZIndex = 5
        Instance.new("UICorner", tpAtualizarBtn).CornerRadius = UDim.new(0, 6)
        addWhiteStroke(tpAtualizarBtn)

        local tpTeleportarBtn = Instance.new("TextButton", molduraTPPlayer)
        tpTeleportarBtn.Size = UDim2.new(1, -20, 0, 32)
        tpTeleportarBtn.Position = UDim2.new(0, 10, 0, 110)
        tpTeleportarBtn.BackgroundColor3 = COR_BOTAO_ATIVO
        tpTeleportarBtn.Text = "TELEPORTAR"
        tpTeleportarBtn.TextColor3 = COR_TEXTO
        tpTeleportarBtn.Font = FONTE_TEXTO
        tpTeleportarBtn.TextSize = 13
        tpTeleportarBtn.ZIndex = 5
        Instance.new("UICorner", tpTeleportarBtn).CornerRadius = UDim.new(0, 6)
        addWhiteStroke(tpTeleportarBtn)

        local function fecharDropdownTP()
            tpPlayerDropdown.Visible = false
            tpPlayerSearch.Text = ""
            tpAtualizarBtn.Visible = true
            tpTeleportarBtn.Visible = true
        end

        local function atualizarListaTP(filtro)
            for _, c in ipairs(tpPlayerLista:GetChildren()) do
                if c:IsA("TextButton") then
                    c:Destroy()
                end
            end

            if tpPlayerSelecionado and tpPlayerSelecionado.Parent ~= PlayersService then
                tpPlayerSelecionado = nil
                tpPlayerBtn.Text = "Selecionar Jogador ▼"
                tpPlayerBtn.TextColor3 = COR_TEXTO
            end

            local jogadores = PlayersService:GetPlayers()
            table.sort(jogadores, function(a, b)
                return string.lower(a.Name) < string.lower(b.Name)
            end)

            filtro = string.lower(filtro or "")

            for _, p in ipairs(jogadores) do
                if p ~= player and string.find(string.lower(p.Name), filtro, 1, true) then
                    local item = Instance.new("TextButton", tpPlayerLista)
                    item.Size = UDim2.new(1, 0, 0, 30)
                    item.BackgroundColor3 = Color3.fromRGB(60, 40, 80)
                    item.Text = p.Name
                    item.TextColor3 = (tpPlayerSelecionado == p)
                        and Color3.fromRGB(150, 255, 150)
                        or COR_TEXTO
                    item.Font = FONTE_TEXTO
                    item.TextSize = 12
                    item.TextXAlignment = Enum.TextXAlignment.Left
                    item.ZIndex = 10001
                    Instance.new("UIPadding", item).PaddingLeft = UDim.new(0, 8)
                    Instance.new("UICorner", item).CornerRadius = UDim.new(0, 4)

                    item.MouseButton1Click:Connect(function()
                        vibrar()
                        tpPlayerSelecionado = p
                        tpPlayerBtn.Text = p.Name .. " ▼"
                        tpPlayerBtn.TextColor3 = Color3.fromRGB(150, 255, 150)
                        fecharDropdownTP()
                        atualizarListaTP("")
                    end)
                end
            end
        end

        local function abrirDropdownTP()
            atualizarListaTP("")
            tpPlayerDropdown.Visible = true
            tpAtualizarBtn.Visible = false
            tpTeleportarBtn.Visible = false
        end

        tpPlayerBtn.MouseButton1Click:Connect(function()
            vibrar()
            if tpPlayerDropdown.Visible then
                fecharDropdownTP()
            else
                abrirDropdownTP()
            end
        end)

        tpPlayerVoltarBtn.MouseButton1Click:Connect(function()
            vibrar()
            fecharDropdownTP()
        end)

        tpPlayerSearch:GetPropertyChangedSignal("Text"):Connect(function()
            atualizarListaTP(tpPlayerSearch.Text)
        end)

        tpAtualizarBtn.MouseButton1Click:Connect(function()
            vibrar()
            tpPlayerSelecionado = nil
            tpPlayerBtn.Text = "Selecionar Jogador ▼"
            tpPlayerBtn.TextColor3 = COR_TEXTO
            atualizarListaTP("")
            tpAtualizarBtn.Text = "Jogadores atualizados"
            task.delay(1.5, function()
                if tpAtualizarBtn and tpAtualizarBtn.Parent then
                    tpAtualizarBtn.Text = "Atualizar jogadores"
                end
            end)
        end)

        tpTeleportarBtn.MouseButton1Click:Connect(function()
            vibrar()
            if not tpPlayerSelecionado then
                tpTeleportarBtn.Text = " Selecione um jogador!"
                tpTeleportarBtn.BackgroundColor3 = Color3.fromRGB(180, 60, 60)
                task.delay(2, function()
                    if tpTeleportarBtn and tpTeleportarBtn.Parent then
                        tpTeleportarBtn.Text = "TELEPORTAR"
                        tpTeleportarBtn.BackgroundColor3 = COR_BOTAO_ATIVO
                    end
                end)
                return
            end

            local char = player.Character
            local alvoChar = tpPlayerSelecionado.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local alvoHrp = alvoChar and alvoChar:FindFirstChild("HumanoidRootPart")
            if not hrp or not alvoHrp then return end

            local alvoCFrame = alvoHrp.CFrame * CFrame.new(0, 0, 5)
            local dist = (alvoCFrame.Position - hrp.Position).Magnitude
            local tempo = math.max(dist / 200, 0.05)

            tpTeleportarBtn.Text = " Voando..."
            tpTeleportarBtn.BackgroundColor3 = Color3.fromRGB(255, 200, 80)

            local tw = TweenService:Create(hrp, TweenInfo.new(tempo, Enum.EasingStyle.Linear), {CFrame = alvoCFrame})
            tw:Play()
            tw.Completed:Wait()

            tpTeleportarBtn.Text = " Chegou!"
            tpTeleportarBtn.BackgroundColor3 = Color3.fromRGB(80, 180, 80)
            task.delay(2, function()
                if tpTeleportarBtn and tpTeleportarBtn.Parent then
                    tpTeleportarBtn.Text = "TELEPORTAR"
                    tpTeleportarBtn.BackgroundColor3 = COR_BOTAO_ATIVO
                end
            end)
