        observarAcaoBtn.ZIndex = 5
        Instance.new("UICorner", observarAcaoBtn).CornerRadius = UDim.new(0, 6)
        addWhiteStroke(observarAcaoBtn)

        local function fecharDropdownObservar()
            observarDropdown.Visible = false
            observarSearch.Text = ""
            observarAtualizarBtn.Visible = true
            observarAcaoBtn.Visible = true
        end

        local function pararDeObservar()
            observandoPlayer = false
            local camera = workspace.CurrentCamera
            if camera then
                camera.CameraType = Enum.CameraType.Custom
                local charLocal = player.Character
                local humanoidLocal = charLocal and charLocal:FindFirstChildOfClass("Humanoid")
                if humanoidLocal then
                    camera.CameraSubject = humanoidLocal
                end
            end
            observarAcaoBtn.Text = "OBSERVAR PLAYER"
            observarAcaoBtn.BackgroundColor3 = COR_BOTAO_ATIVO
        end

        local function atualizarListaObservar(filtro)
            for _, c in ipairs(observarLista:GetChildren()) do
                if c:IsA("TextButton") then
                    c:Destroy()
                end
            end

            if observarSelecionado and observarSelecionado.Parent ~= PlayersService then
                if observandoPlayer then pararDeObservar() end
                observarSelecionado = nil
                if observarCharacterConn then
                    observarCharacterConn:Disconnect()
                    observarCharacterConn = nil
                end
                observarPlayerBtn.Text = "Selecionar Jogador ▼"
                observarPlayerBtn.TextColor3 = COR_TEXTO
            end

            local jogadores = PlayersService:GetPlayers()
            table.sort(jogadores, function(a, b)
                return string.lower(a.Name) < string.lower(b.Name)
            end)

            filtro = string.lower(filtro or "")
            for _, p in ipairs(jogadores) do
                if p ~= player and string.find(string.lower(p.Name), filtro, 1, true) then
                    local item = Instance.new("TextButton", observarLista)
                    item.Size = UDim2.new(1, 0, 0, 30)
                    item.BackgroundColor3 = Color3.fromRGB(60, 40, 80)
                    item.Text = p.Name
                    item.TextColor3 = (observarSelecionado == p)
                        and Color3.fromRGB(150, 255, 150)
                        or COR_TEXTO
                    item.Font = FONTE_TEXTO
                    item.TextSize = 12
                    item.TextXAlignment = Enum.TextXAlignment.Left
                    item.ZIndex = 10001
                    Instance.new("UIPadding", item).PaddingLeft = UDim.new(0, 8)
                    Instance.new("UICorner", item).CornerRadius = UDim.new(0, 4)

                    item.MouseButton1Click:Connect(function()
                        vibrar()
                        if observandoPlayer then pararDeObservar() end
                        if observarCharacterConn then
                            observarCharacterConn:Disconnect()
                            observarCharacterConn = nil
                        end
                        observarSelecionado = p
                        observarCharacterConn = p.CharacterAdded:Connect(function(novoChar)
                            if not observandoPlayer then return end
                            local novoHumanoid = novoChar:WaitForChild("Humanoid", 5)
                            if novoHumanoid and observandoPlayer and observarSelecionado == p then
                                local camera = workspace.CurrentCamera
                                if camera then
                                    camera.CameraType = Enum.CameraType.Custom
                                    camera.CameraSubject = novoHumanoid
                                end
                            end
                        end)
                        observarPlayerBtn.Text = p.Name .. " ▼"
                        observarPlayerBtn.TextColor3 = Color3.fromRGB(150, 255, 150)
                        fecharDropdownObservar()
                        atualizarListaObservar("")
                    end)
                end
            end
        end

        local function abrirDropdownObservar()
            atualizarListaObservar("")
            observarDropdown.Visible = true
            observarAtualizarBtn.Visible = false
            observarAcaoBtn.Visible = false
        end

        observarPlayerBtn.MouseButton1Click:Connect(function()
            vibrar()
            if observarDropdown.Visible then
                fecharDropdownObservar()
            else
                abrirDropdownObservar()
            end
        end)

        observarVoltarBtn.MouseButton1Click:Connect(function()
            vibrar()
            fecharDropdownObservar()
        end)

        observarSearch:GetPropertyChangedSignal("Text"):Connect(function()
            atualizarListaObservar(observarSearch.Text)
        end)

        observarAtualizarBtn.MouseButton1Click:Connect(function()
            vibrar()
            observarSelecionado = nil
            if observandoPlayer then pararDeObservar() end
            if observarCharacterConn then
                observarCharacterConn:Disconnect()
                observarCharacterConn = nil
            end
            observarPlayerBtn.Text = "Selecionar Jogador ▼"
            observarPlayerBtn.TextColor3 = COR_TEXTO
            atualizarListaObservar("")
            observarAtualizarBtn.Text = "Jogadores atualizados"
            task.delay(1.5, function()
                if observarAtualizarBtn and observarAtualizarBtn.Parent then
                    observarAtualizarBtn.Text = "Atualizar jogadores"
                end
            end)
        end)

        observarAcaoBtn.MouseButton1Click:Connect(function()
            vibrar()
            if observandoPlayer then
                pararDeObservar()
                return
            end

            if not observarSelecionado or observarSelecionado.Parent ~= PlayersService then
                observarAcaoBtn.Text = "SELECIONE UM JOGADOR"
                task.delay(1.5, function()
                    if observarAcaoBtn and observarAcaoBtn.Parent and not observandoPlayer then
                        observarAcaoBtn.Text = "OBSERVAR PLAYER"
                    end
                end)
                return
            end

            local alvoChar = observarSelecionado.Character
            local alvoHumanoid = alvoChar and alvoChar:FindFirstChildOfClass("Humanoid")
            if not alvoHumanoid or alvoHumanoid.Health <= 0 then
                observarAcaoBtn.Text = "JOGADOR SEM PERSONAGEM"
                task.delay(1.5, function()
                    if observarAcaoBtn and observarAcaoBtn.Parent and not observandoPlayer then
                        observarAcaoBtn.Text = "OBSERVAR PLAYER"
                    end
                end)
                return
            end

            local camera = workspace.CurrentCamera
            if not camera then return end
            camera.CameraType = Enum.CameraType.Custom
            camera.CameraSubject = alvoHumanoid
            observandoPlayer = true
            observarAcaoBtn.Text = "PARAR DE OBSERVAR"
            observarAcaoBtn.BackgroundColor3 = Color3.fromRGB(180, 75, 75)
        end)

        PlayersService.PlayerRemoving:Connect(function(saiu)
            if saiu == observarSelecionado then
                if observandoPlayer then pararDeObservar() end
                observarSelecionado = nil
                if observarCharacterConn then
                    observarCharacterConn:Disconnect()
                    observarCharacterConn = nil
                end
                observarPlayerBtn.Text = "Selecionar Jogador ▼"
                observarPlayerBtn.TextColor3 = COR_TEXTO
                fecharDropdownObservar()
            end
        end)

        PlayersService.PlayerAdded:Connect(function()
            if observarDropdown.Visible then
                atualizarListaObservar(observarSearch.Text)
            end
        end)

        player.CharacterAdded:Connect(function()
            if observarDropdown and observarDropdown.Parent then
                fecharDropdownObservar()
            end
            if observandoPlayer and observarSelecionado and observarSelecionado.Character then
                local alvoHumanoid = observarSelecionado.Character:FindFirstChildOfClass("Humanoid")
                local camera = workspace.CurrentCamera
                if camera and alvoHumanoid then camera.CameraSubject = alvoHumanoid end
            end
        end)
        -- ===================== FIM OBSERVAR PLAYER =====================

        contPvp.CanvasSize = UDim2.new(0, 0, 0, 490)
    end
end
