-- ===================== AUTO CHEST (OTIMIZADO) =====================
local autoChestAtivo = false
local autoChestTask = nil
local chestTween = nil
local chestNoclip = nil
local chestColOrig = {}

local ILHAS_CHEST = {
    "Starter Island","Marine Fortress","Middle Town","Jungle","Pirate Village","Desert",
    "Frozen Village","Marine Ford","Sky Island","Prison","Colosseum","Magma Village",
    "Underwater City","Fountain City","Upper Town","Cafe","Mini Sky Island",
    "Kingdom of Rose","Green Zone","Graveyard","Snow Mountain","Hot and Cold","Cursed Ship",
    "Ice Castle","Forgotten Island","Port Town","Hydra Island","Great Tree","Floating Turtle",
    "Castle on the Sea","Haunted Castle","Sea of Treats","Tiki Outpost","Kitsune Island"
}
local ilhaChestIndex = 1

local molduraChest = criarMoldura(contMain, 40, 110, "Auto Chest (Farm Rápido)")
local chestBox, chestBtn = criarToggle(molduraChest)
local chestCircle = chestBox:FindFirstChild("Circle")

local chestStatus = Instance.new("TextLabel", molduraChest)
chestStatus.Size = UDim2.new(1, -20, 0, 40)
chestStatus.Position = UDim2.new(0, 10, 0, 58)
chestStatus.BackgroundTransparency = 1
chestStatus.Text = "Desativado"
chestStatus.TextColor3 = COR_TEXTO_SUB
chestStatus.Font = FONTE_TEXTO
chestStatus.TextSize = 11
chestStatus.TextWrapped = true
chestStatus.TextXAlignment = Enum.TextXAlignment.Center

local function ligarNoclipChest()
    if chestNoclip then return end
    chestNoclip = RunService.Stepped:Connect(function()
        local char = player.Character
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") then
                if chestColOrig[p] == nil then chestColOrig[p] = p.CanCollide end
                p.CanCollide = false
            end
        end
        local root = char:FindFirstChild("HumanoidRootPart")
        if root then root.AssemblyLinearVelocity = Vector3.zero end
    end)
end

local function desligarNoclipChest()
    if chestNoclip then chestNoclip:Disconnect() chestNoclip = nil end
    for p, v in pairs(chestColOrig) do if p and p.Parent then p.CanCollide = v end end
    chestColOrig = {}
end

local function pegarBau(obj)
    local char = player.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    local alvo = obj:IsA("BasePart") and obj or obj:FindFirstChildWhichIsA("BasePart", true)
    
    if root and alvo then
        root.CFrame = alvo.CFrame
        if firetouchinterest then 
            pcall(function() 
                firetouchinterest(root, alvo, 0) 
                firetouchinterest(root, alvo, 1) 
            end) 
        end
    end
end

local function loopAutoChest()
    while autoChestAtivo do
        pcall(function()
            local char = player.Character
            if not char or not char:FindFirstChild("HumanoidRootPart") then return end
            local root = char.HumanoidRootPart
            
            local pasta = workspace:FindFirstChild("ChestModels")
            local melhorBau, menorDist = nil, math.huge

            if pasta then
                for _, obj in ipairs(pasta:GetChildren()) do
                    if (obj.Name == "SilverChest" or obj.Name == "GoldChest" or obj.Name == "DiamondChest") then
                        local alvo = obj:IsA("BasePart") and obj or obj:FindFirstChildWhichIsA("BasePart", true)
                        if alvo then
                            local dist = (alvo.Position - root.Position).Magnitude
                            if dist < menorDist then
                                menorDist = dist
                                melhorBau = obj
                            end
                        end
                    end
                end
            end

            if melhorBau then
 chestStatus.Text = "Pegando baú (" .. math.floor(menorDist) .. "m)..."
                local alvo = melhorBau:IsA("BasePart") and melhorBau or melhorBau:FindFirstChildWhichIsA("BasePart", true)
                
                if alvo then
                    local tempo = math.max(menorDist / _G.FarmSpeed, 0.1)
                    local tw = TweenService:Create(root, TweenInfo.new(tempo, Enum.EasingStyle.Linear), { CFrame = alvo.CFrame })
                    chestTween = tw
                    ligarNoclipChest()
                    tw:Play()
                    
                    local inicio = tick()
                    while autoChestAtivo and tw.PlaybackState == Enum.PlaybackState.Playing and tick() - inicio < tempo + 1 do
                        task.wait(0.1)
                    end
                    
                    tw:Cancel()
                    if chestTween == tw then chestTween = nil end
                    desligarNoclipChest()
                    
                    if autoChestAtivo and melhorBau:IsDescendantOf(workspace) then
                        pegarBau(melhorBau)
                    end
                    task.wait(0.5)
                end
            else
                local nomeIlha = ILHAS_CHEST[ilhaChestIndex]
 chestStatus.Text = "Viajando p/ " .. nomeIlha
                local ilhaModel = workspace:FindFirstChild(nomeIlha)
                
                if ilhaModel then
                    local pos = nil
                    if ilhaModel:IsA("BasePart") then 
                        pos = ilhaModel.Position
                    elseif ilhaModel:IsA("Model") then
                        local ok, cf = pcall(function() return ilhaModel:GetBoundingBox() end)
                        if ok and cf then pos = cf.Position end
                    end
                    
                    if pos then
                        ligarNoclipChest()
                        root.CFrame = CFrame.new(pos + Vector3.new(0, 20, 0))
                        task.wait(1.5)
                        desligarNoclipChest()
                    end
                end
                
                ilhaChestIndex = ilhaChestIndex + 1
                if ilhaChestIndex > #ILHAS_CHEST then ilhaChestIndex = 1 end
            end
        end)
        task.wait(0.5)
    end
end

chestBtn.MouseButton1Click:Connect(function()
    vibrar()
    autoChestAtivo = not autoChestAtivo
    TweenService:Create(chestBox, TweenInfo.new(0.15), {BackgroundColor3 = autoChestAtivo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)}):Play()
    if chestCircle then
        TweenService:Create(chestCircle, TweenInfo.new(0.15), {Position = autoChestAtivo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)}):Play()
    end

    if autoChestAtivo then
 chestStatus.TextColor3 = COR_BOLINHA_VERDE
 chestStatus.Text = "Procurando baús..."
        autoChestTask = task.spawn(loopAutoChest)
    else
 chestStatus.TextColor3 = COR_TEXTO_SUB
 chestStatus.Text = "Desativado"
        if autoChestTask then pcall(function() task.cancel(autoChestTask) end); autoChestTask = nil end
        if chestTween then chestTween:Cancel(); chestTween = nil end
        desligarNoclipChest()
    end
end)
-- ===================== FIM AUTO CHEST =====================
    contMain.CanvasSize = UDim2.new(0, 0, 0, 170)
end
