        filtro = string.lower(filtro or "")
        for _, nome in ipairs(baitsList) do
            if string.find(string.lower(nome), filtro, 1, true) then
                local item = Instance.new("TextButton", listaBait)
                item.Size = UDim2.new(1, 0, 0, 30)
                item.BackgroundColor3 = Color3.fromRGB(60, 40, 80)
                item.Text = nome
                item.TextColor3 = COR_TEXTO
                item.Font = FONTE_TEXTO
                item.TextSize = 12
                item.TextXAlignment = Enum.TextXAlignment.Left
                item.ZIndex = 10001
                Instance.new("UIPadding", item).PaddingLeft = UDim.new(0, 8)
                Instance.new("UICorner", item).CornerRadius = UDim.new(0, 4)

                item.MouseButton1Click:Connect(function()
                    vibrar()
                    baitSelecionada = nome
                    baitSelectBtn.Text = nome .. " ▼"
                    dropdownBait.Visible = false
                    searchBait.Text = ""
                    atualizarListaBait("")
                    baitStatus.TextColor3 = Color3.fromRGB(255, 255, 255)
                    baitStatus.Text = "Selecionada: " .. nome .. " (10 unidades por compra)"
                end)
            end
        end
    end

    local function abrirDropdownBait()
        dropdownBait.Visible = true
        atualizarListaBait("")
    end

    baitSelectBtn.MouseButton1Click:Connect(function()
        vibrar()
        if dropdownBait.Visible then
            dropdownBait.Visible = false
        else
            abrirDropdownBait()
        end
    end)

    baitVoltarBtn.MouseButton1Click:Connect(function()
        vibrar()
        dropdownBait.Visible = false
        searchBait.Text = ""
        atualizarListaBait("")
    end)

    atualizarBaitBtn.MouseButton1Click:Connect(function()
        vibrar()
        baitSelecionada = nil
        baitSelectBtn.Text = "Selecionar Isca ▼"
        dropdownBait.Visible = false
        searchBait.Text = ""
        atualizarListaBait("")
        baitStatus.TextColor3 = COR_TEXTO_SUB
        baitStatus.Text = "Lista reiniciada. Toque em Selecionar Isca para escolher outra."
    end)

    searchBait:GetPropertyChangedSignal("Text"):Connect(function()
        atualizarListaBait(searchBait.Text)
    end)

    comprarBaitBtn.MouseButton1Click:Connect(function()
        vibrar()
        if compraBaitEmAndamento then return end

        if not baitSelecionada then
            baitStatus.TextColor3 = COR_ALERTA
            baitStatus.Text = "Primeiro selecione uma isca."
            abrirDropdownBait()
            return
        end

        compraBaitEmAndamento = true
        comprarBaitBtn.Active = false
        comprarBaitBtn.AutoButtonColor = false
        comprarBaitBtn.Text = "COMPRANDO..."
        baitStatus.TextColor3 = COR_TEXTO_SUB
        baitStatus.Text = "Enviando pedido de 10x " .. baitSelecionada .. "..."

        task.spawn(function()
            local ok, resposta = false, nil
            local compraConfirmada = false
            local envioSemRetorno = false
            local rfCraft = getRemoteCraft()

            if not rfCraft then
                resposta = "Remote RF/Craft não foi encontrado."
            else
                ok, resposta = pcall(function()
                    if rfCraft:IsA("RemoteFunction") then
                        -- O sistema de Fishing do jogo faz a compra em lote de 10
                        -- usando apenas o nome da isca no RF/Craft.
                        -- Não enviar a quantidade como terceiro argumento, pois
                        -- isso pode fazer o servidor interpretar a solicitação
                        -- incorretamente e retornar "Max stack reached!".
                        return rfCraft:InvokeServer("Craft", baitSelecionada)
                    else
                        rfCraft:FireServer("Craft", baitSelecionada, 10)
                        envioSemRetorno = true
                        return "Pedido enviado ao servidor."
                    end
                end)

                if ok and not envioSemRetorno then
                    if resposta == true then
                        compraConfirmada = true
                    elseif type(resposta) == "table" then
                        compraConfirmada = resposta.Success == true
                            or resposta.success == true
                            or resposta.Successful == true
                            or resposta.successful == true
                    elseif type(resposta) == "string" then
                        local lower = string.lower(resposta)
                        local recusado = string.find(lower, "error", 1, true)
                            or string.find(lower, "need", 1, true)
                            or string.find(lower, "not", 1, true)
                            or string.find(lower, "insufficient", 1, true)
                            or string.find(lower, "failed", 1, true)
                            or string.find(lower, "missing", 1, true)
                            or string.find(lower, "recus", 1, true)
                            or string.find(lower, "insuficiente", 1, true)
                            or string.find(lower, "não", 1, true)
                            or string.find(lower, "nao", 1, true)
                        local confirmacoes = {
                            "success", "successfully", "crafted", "purchased", "bought",
                            "obtained", "completed", "comprado", "compra realizada",
                            "fabricado", "criado", "obtido", "sucesso", "concluido", "concluído"
                        }
                        if not recusado then
                            for _, palavra in ipairs(confirmacoes) do
                                if string.find(lower, palavra, 1, true) then
                                    compraConfirmada = true
                                    break
                                end
                            end
                        end
                    end
                end
            end

            if not ok then
                baitStatus.TextColor3 = COR_ALERTA
                baitStatus.Text = "Erro ao comprar: " .. tostring(resposta)
            elseif resposta == false then
                baitStatus.TextColor3 = COR_ALERTA
                baitStatus.Text = "Servidor recusou. Confira dinheiro, materiais e receita desbloqueada."
            elseif compraConfirmada then
                baitStatus.TextColor3 = COR_BOLINHA_VERDE
                if type(resposta) == "string" and resposta ~= "" then
                    baitStatus.Text = resposta
                else
                    baitStatus.Text = "Compra confirmada: 10x " .. baitSelecionada .. "!"
                end
            elseif type(resposta) == "string" and resposta ~= "" then
                local lower = string.lower(resposta)
                local recusado = string.find(lower, "error", 1, true)
                    or string.find(lower, "need", 1, true)
                    or string.find(lower, "not", 1, true)
                    or string.find(lower, "insufficient", 1, true)
                    or string.find(lower, "failed", 1, true)
                    or string.find(lower, "missing", 1, true)
                    or string.find(lower, "recus", 1, true)
                    or string.find(lower, "insuficiente", 1, true)
                    or string.find(lower, "não", 1, true)
                    or string.find(lower, "nao", 1, true)
                if recusado then
                    baitStatus.TextColor3 = COR_ALERTA
                    baitStatus.Text = resposta
                else
                    baitStatus.TextColor3 = Color3.fromRGB(255, 255, 255)
                    baitStatus.Text = envioSemRetorno
                        and "Pedido enviado ao servidor, mas ainda não houve confirmação da compra."
                        or "O servidor não confirmou a compra. Confira a mochila antes de tentar novamente."
                end
            else
                baitStatus.TextColor3 = Color3.fromRGB(255, 255, 255)
                baitStatus.Text = "O servidor não retornou confirmação da compra. Confira a mochila."
            end

            comprarBaitBtn.Text = "COMPRAR 10x"
            comprarBaitBtn.Active = true
            comprarBaitBtn.AutoButtonColor = true
            compraBaitEmAndamento = false
        end)
    end)

    contShop.CanvasSize = UDim2.new(0, 0, 0, 300)
end
