-- =====================================================
-- CELESTIAL HUB - ABA COMANDOS
-- Interface própria: sem painel Admin 1/2 e sem Command Bar.
-- Os comandos são apresentados individualmente como toggles ou botões.
-- =====================================================
do
    local comandosTab = frame:FindFirstChild("ContainerAba_comandos")
    if comandosTab then
        -- Esta aba usa uma lista interna própria. Desativar a rolagem do
        -- container externo evita duas ScrollingFrames disputando o gesto.
        comandosTab.ScrollingEnabled = false
        comandosTab.AutomaticCanvasSize = Enum.AutomaticSize.None
        comandosTab.CanvasSize = UDim2.new(0, 0, 0, comandosTab.AbsoluteSize.Y)
        comandosTab.CanvasPosition = Vector2.new(0, 0)
        comandosTab.ElasticBehavior = Enum.ElasticBehavior.Never
        comandosTab.ClipsDescendants = true
        comandosTab:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
            comandosTab.CanvasSize = UDim2.new(0, 0, 0, comandosTab.AbsoluteSize.Y)
        end)
        -- O título "⌘ COMANDOS" é criado junto com as demais abas,
        -- na mesma posição e no mesmo padrão visual de SETTINGS, MAIN etc.

        local topo = Instance.new("TextLabel")
        topo.Name = "DescricaoComandos"
        topo.Size = UDim2.new(1, -20, 0, 30)
        topo.Position = UDim2.new(0, 10, 0, 36)
        topo.BackgroundTransparency = 1
        topo.Text = "428 comandos do Celestial Hub • selecione uma ação abaixo"
        topo.TextColor3 = COR_TEXTO_SUB
        topo.Font = FONTE_TEXTO
        topo.TextSize = 9
        topo.TextXAlignment = Enum.TextXAlignment.Left
        topo.TextWrapped = true
        topo.Parent = comandosTab

        local busca = Instance.new("TextBox")
        busca.Name = "BuscarComando"
        busca.Size = UDim2.new(1, -20, 0, 30)
        busca.Position = UDim2.new(0, 10, 0, 68)
        busca.BackgroundColor3 = COR_CARD
        busca.BorderSizePixel = 0
        busca.PlaceholderText = "Pesquisar comando..."
        busca.Text = ""
        busca.TextColor3 = COR_TEXTO
        busca.PlaceholderColor3 = COR_TEXTO_SUB
        busca.Font = FONTE_TEXTO
        busca.TextSize = 10
        busca.ClearTextOnFocus = false
        busca.Parent = comandosTab
        Instance.new("UICorner", busca).CornerRadius = UDim.new(0, 6)
        addWhiteStroke(busca)

        local lista = Instance.new("ScrollingFrame")
        lista.Name = "ListaComandos"
        lista.Size = UDim2.new(1, -20, 1, -112)
        lista.Position = UDim2.new(0, 10, 0, 104)
        lista.BackgroundColor3 = COR_PAINEL
        lista.BackgroundTransparency = 0.12
        lista.BorderSizePixel = 0
        lista.ScrollBarThickness = 5
        lista.ScrollingDirection = Enum.ScrollingDirection.Y
        lista.ScrollingEnabled = true
        lista.Active = true
        lista.ElasticBehavior = Enum.ElasticBehavior.Never
        lista.AutomaticCanvasSize = Enum.AutomaticSize.None
        lista.CanvasSize = UDim2.new(0, 0, 0, 0)
        lista.ClipsDescendants = true
        lista.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
        lista.Parent = comandosTab
        Instance.new("UICorner", lista).CornerRadius = UDim.new(0, 7)
        local layout = Instance.new("UIListLayout", lista)
        layout.Padding = UDim.new(0, 4)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        local padding = Instance.new("UIPadding", lista)
        padding.PaddingTop = UDim.new(0, 5)
        padding.PaddingBottom = UDim.new(0, 5)
        padding.PaddingLeft = UDim.new(0, 5)
        padding.PaddingRight = UDim.new(0, 5)

        local function atualizarCanvasComandos()
            lista.CanvasSize = UDim2.new(
                0, 0, 0,
                math.max(0, layout.AbsoluteContentSize.Y
                    + padding.PaddingTop.Offset
                    + padding.PaddingBottom.Offset + 2)
            )
        end
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(atualizarCanvasComandos)
        lista:GetPropertyChangedSignal("AbsoluteSize"):Connect(atualizarCanvasComandos)

        local enginePronto = false
        local engineCarregando = false
        local function garantirEngine()
            if enginePronto and type(execCmd) == "function" then return true end
            if engineCarregando then
                repeat task.wait(0.1) until not engineCarregando
                return enginePronto and type(execCmd) == "function"
            end
            engineCarregando = true
            local ok, err = pcall(function()
                if type(execCmd) ~= "function" then
                    if type(loadstring) ~= "function" then error("Este executor não oferece suporte a loadstring.") end
                    local fn, compileError = loadstring(CelestialHubInfiniteYieldSource)
                    if not fn then error(compileError or "Falha ao preparar os comandos.") end
                    fn()
                    -- Esconde a interface original imediatamente para não exibir o painel nem a Command Bar.
                    pcall(function()
                        local raiz = _G.CelestialHubAdmin1Root
                        if raiz and raiz:IsA("GuiObject") then raiz.Visible = false end
                    end)
                    task.wait(0.2)
                end
                if type(execCmd) ~= "function" then error("O mecanismo de comandos não foi inicializado.") end
                -- Remove somente a interface visual do Infinite Yield; o executor dos comandos permanece ativo.
                pcall(function()
                    if _G.CelestialHubAdmin1Root and _G.CelestialHubAdmin1Root.Parent then
                        _G.CelestialHubAdmin1Root:Destroy()
                    end
                end)
                pcall(function()
                    if _G.CelestialHubAdmin1OwnedScreen and _G.CelestialHubAdmin1OwnedScreen.Parent then
                        _G.CelestialHubAdmin1OwnedScreen:Destroy()
                    end
                end)
                _G.CelestialHubAdmin1Gui = nil
                _G.CelestialHubAdmin1Root = nil
                _G.CelestialHubAdmin1OwnedScreen = nil
                _G.CelestialHubAdmin1Unload = nil
                enginePronto = true
            end)
            engineCarregando = false
            if not ok then
                warn("[Celestial Hub COMANDOS] " .. tostring(err))
                return false
            end
            return true
        end

        -- =====================================================
        -- CONTROLES RÁPIDOS NAS ABAS CORRETAS
        -- Os comandos originais continuam intactos na lista de 428 comandos.
        -- =====================================================
        local function criarAcaoUI(parent, nome, texto, y, callback, altura)
            local card = Instance.new("Frame")
            card.Name = nome
            card.Size = UDim2.new(1, -20, 0, altura or 82)
            card.Position = UDim2.new(0, 10, 0, y)
            card.BackgroundColor3 = COR_CARD
            card.BorderSizePixel = 0
            card.Parent = parent
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 7)
            local titulo = Instance.new("TextLabel")
            titulo.BackgroundTransparency = 1
            titulo.Position = UDim2.new(0, 10, 0, 5)
            titulo.Size = UDim2.new(1, -20, 0, 22)
            titulo.Font = FONTE_TEXTO
            titulo.TextSize = 12
            titulo.TextColor3 = COR_TEXTO
            titulo.TextXAlignment = Enum.TextXAlignment.Left
            titulo.Text = texto
            titulo.Parent = card
            local btn = Instance.new("TextButton")
            btn.Size = UDim2.new(1, -20, 0, 32)
            btn.Position = UDim2.new(0, 10, 0, 38)
            btn.BackgroundColor3 = COR_BOTAO_ATIVO
            btn.Text = "ATIVAR"
            btn.TextColor3 = COR_TEXTO
            btn.Font = FONTE_TEXTO
            btn.TextSize = 11
            btn.Parent = card
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
            addWhiteStroke(btn)
            btn.MouseButton1Click:Connect(function()
                vibrar()
                callback(btn)
            end)
            return card, btn
        end
        local function rodarComando(comando)
            if not garantirEngine() then
                warn("[Celestial Hub] Não foi possível iniciar o mecanismo de comandos.")
                return false
            end
            local ok, err = pcall(function() execCmd(comando, Players.LocalPlayer, true) end)
            if not ok then warn("[Celestial Hub] " .. tostring(err)) end
            return ok
        end
        local function criarToggleVisual(parent, nome, titulo, y, callback, altura)
            local card = Instance.new("Frame")
            card.Name = nome
            card.Size = UDim2.new(1, -20, 0, altura or 64)
            card.Position = UDim2.new(0, 10, 0, y)
            card.BackgroundColor3 = COR_CARD
            card.BorderSizePixel = 0
            card.Parent = parent
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 7)

            local title = Instance.new("TextLabel", card)
            title.BackgroundTransparency = 1
            title.Position = UDim2.new(0, 10, 0, 0)
            title.Size = UDim2.new(1, -82, 1, 0)
            title.Text = titulo
            title.TextColor3 = COR_TEXTO
            title.Font = FONTE_TEXTO
            title.TextSize = 12
            title.TextWrapped = true
            title.TextXAlignment = Enum.TextXAlignment.Left
            title.TextYAlignment = Enum.TextYAlignment.Center

            local box = Instance.new("Frame", card)
            box.Size = UDim2.new(0, 48, 0, 26)
            box.AnchorPoint = Vector2.new(1, 0.5)
            box.Position = UDim2.new(1, -12, 0.5, 0)
            box.BackgroundColor3 = Color3.fromRGB(60, 60, 70)
            box.BorderSizePixel = 0
            Instance.new("UICorner", box).CornerRadius = UDim.new(1, 0)
            local circle = Instance.new("Frame", box)
            circle.Name = "Circle"
            circle.Size = UDim2.new(0, 20, 0, 20)
            circle.Position = UDim2.new(0, 3, 0.5, -10)
            circle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            circle.BorderSizePixel = 0
            Instance.new("UICorner", circle).CornerRadius = UDim.new(1, 0)
            local hit = Instance.new("TextButton", card)
            hit.Size = UDim2.new(0, 52, 0, 34)
            hit.AnchorPoint = Vector2.new(1, 0.5)
            hit.Position = UDim2.new(1, -10, 0.5, 0)
            hit.BackgroundTransparency = 1
            hit.Text = ""
            hit.Parent = card

            local ativo = false
            local function atualizarVisual()
                TweenService:Create(box, TweenInfo.new(0.15), {
                    BackgroundColor3 = ativo and Color3.fromRGB(0, 120, 220) or Color3.fromRGB(60, 60, 70)
                }):Play()
                TweenService:Create(circle, TweenInfo.new(0.15), {
                    Position = ativo and UDim2.new(0, 25, 0.5, -10) or UDim2.new(0, 3, 0.5, -10)
                }):Play()
            end
            local function definirEstado(novoEstado, silencioso)
                local estadoAnterior = ativo
                ativo = novoEstado
                atualizarVisual()
                if callback then
                    local resultado = callback(ativo, function() definirEstado(false, true) end, silencioso)
                    if resultado == false then
                        ativo = estadoAnterior
                        atualizarVisual()
                    end
                end
            end
            atualizarVisual()
            hit.MouseButton1Click:Connect(function()
                vibrar()
                definirEstado(not ativo, false)
            end)
            return card, definirEstado
        end

        local function criarToggleComando(parent, nome, titulo, y, comandoOn, comandoOff, altura)
            return criarToggleVisual(parent, nome, titulo, y, function(ativo)
                return rodarComando(ativo and comandoOn or comandoOff)
            end, altura or 64)
        end

        -- Calcula o próximo espaço livre com base nos elementos reais da aba.
        -- Isso evita os grandes vãos causados por posições Y fixas.
        local function proximoY(parent)
            local bottom = 36
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("GuiObject") and child.Visible then
                    local y = child.Position.Y.Offset + child.Size.Y.Offset
                    if y > bottom then bottom = y end
                end
            end
            return bottom + 10
        end

        local function criarCampoAplicacao(parent, nome, tituloTexto, placeholder, valorInicial, textoBotao, validar, aplicar)
            local y = proximoY(parent)
            local card = Instance.new("Frame")
            card.Name = nome
            card.Size = UDim2.new(1, -20, 0, 92)
            card.Position = UDim2.new(0, 10, 0, y)
            card.BackgroundColor3 = COR_CARD
            card.BorderSizePixel = 0
            card.Parent = parent
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 7)

            local title = Instance.new("TextLabel", card)
            title.BackgroundTransparency = 1
            title.Position = UDim2.new(0, 10, 0, 5)
            title.Size = UDim2.new(1, -20, 0, 20)
            title.Text = tituloTexto
            title.TextColor3 = COR_TEXTO
            title.Font = FONTE_TEXTO
            title.TextSize = 12
            title.TextXAlignment = Enum.TextXAlignment.Left

            local input = Instance.new("TextBox", card)
            input.Size = UDim2.new(0.48, -12, 0, 34)
            input.Position = UDim2.new(0, 10, 0, 42)
            input.BackgroundColor3 = COR_PAINEL
            input.TextColor3 = COR_TEXTO
            input.PlaceholderText = placeholder
            input.Text = valorInicial
            input.Font = FONTE_TEXTO
            input.TextSize = 12
            input.ClearTextOnFocus = false
            input.BorderSizePixel = 0
            input.Parent = card
            Instance.new("UICorner", input).CornerRadius = UDim.new(0, 6)

            local apply = Instance.new("TextButton", card)
            apply.Size = UDim2.new(0.48, -12, 0, 34)
            apply.Position = UDim2.new(0.52, 2, 0, 42)
            apply.BackgroundColor3 = COR_BOTAO_ATIVO
            apply.Text = textoBotao
            apply.TextColor3 = COR_TEXTO
            apply.Font = FONTE_TEXTO
            apply.TextSize = 11
            apply.BorderSizePixel = 0
            apply.Parent = card
            Instance.new("UICorner", apply).CornerRadius = UDim.new(0, 6)

            input:GetPropertyChangedSignal("Text"):Connect(function()
                apply.Text = textoBotao
                apply.BackgroundColor3 = COR_BOTAO_ATIVO
            end)
            apply.MouseButton1Click:Connect(function()
                vibrar()
                local value = validar(input.Text)
                if value == nil then
                    apply.Text = "VALOR INVÁLIDO"
                    apply.BackgroundColor3 = COR_ALERTA
                    return
                end
                local ok = aplicar(value)
                if ok then
                    apply.Text = "APLICADO"
                    apply.BackgroundColor3 = COR_BOLINHA_VERDE
                else
                    apply.Text = "FALHA AO APLICAR"
                    apply.BackgroundColor3 = COR_ALERTA
                end
                -- O botão continua clicável; o texto volta ao padrão após o retorno visual.
                task.delay(1.5, function()
                    if apply and apply.Parent then
                        apply.Text = textoBotao
                        apply.BackgroundColor3 = COR_BOTAO_ATIVO
                    end
                end)
            end)
            return card
        end

        local function criarToggleAcaoUnica(parent, nome, titulo, comando)
            local card, definirEstado
            local y = 36
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("GuiObject") and child.Visible then
                    y = math.max(y, child.Position.Y.Offset + child.Size.Y.Offset + 10)
                end
            end
            card, definirEstado = criarToggleVisual(parent, nome, titulo, y, function(ativo, resetar)
                if not ativo then return end
                local ok = rodarComando(comando)
                if not ok then
                    notify("Celestial Hub", "Não foi possível executar: " .. titulo)
                end
                -- Ações pontuais não ficam ligadas: o switch volta para OFF após disparar.
                task.delay(0.65, function()
                    if card and card.Parent then resetar() end
                end)
            end, 64)
            return card
        end

        local function criarAcaoRapida(parent, nome, titulo, comando)
            local y = proximoY(parent)
            local card, btn = criarAcaoUI(parent, nome, titulo, y, function(b)
                local ok = rodarComando(comando)
                if ok then
                    b.Text = "CONCLUÍDO"
                    b.BackgroundColor3 = COR_BOLINHA_VERDE
                else
                    b.Text = "FALHA • TENTAR NOVAMENTE"
                    b.BackgroundColor3 = COR_ALERTA
                end
            end, 70)
            btn.Position = UDim2.new(0, 10, 0, 32)
            btn.Size = UDim2.new(1, -20, 0, 28)
            return card
        end

        -- =====================================================
        -- ABA KEYBOARD: teclado virtual no estilo da referência.
        -- O título foi personalizado para CELESTIAL HUB.
        -- =====================================================
        local keyboardWindow
local keyboardInputLock -- declarado antes do callback da aba para evitar referência global nil
        local keyboardTab = frame:FindFirstChild("ContainerAba_keyboard")
        if keyboardTab then
            local keyboardCard, openKeyboardButton = criarAcaoUI(
                keyboardTab, "AbrirTecladoCelestial", "Teclado virtual Celestial Hub", proximoY(keyboardTab),
                function(btn)
                    if keyboardWindow then
                        -- O teclado é uma janela flutuante: não bloqueia o ícone do
                        -- hub nem os demais controles fora da própria janela.
                        keyboardWindow.Visible = true
                        btn.Text = "TECLADO ABERTO"
                        task.delay(1, function()
                            if btn and btn.Parent then btn.Text = "ABRIR TECLADO" end
                        end)
                    end
                end, 82
            )
            openKeyboardButton.Text = "ABRIR TECLADO"
            keyboardTab.CanvasSize = UDim2.new(0, 0, 0, proximoY(keyboardTab) + 5)
        end

        -- Compatibilidade: camada antiga mantida invisível e desativada.
        -- Ela não pode capturar toques, pois o teclado agora é uma janela flutuante.
        keyboardInputLock = Instance.new("TextButton")
        keyboardInputLock.Name = "KeyboardInputLock"
        keyboardInputLock.Size = UDim2.new(1, 0, 1, 0)
        keyboardInputLock.Position = UDim2.new(0, 0, 0, 0)
        keyboardInputLock.BackgroundTransparency = 1
        keyboardInputLock.Text = ""
        keyboardInputLock.AutoButtonColor = false
        keyboardInputLock.Active = false
        keyboardInputLock.Modal = false
        keyboardInputLock.Visible = false
        keyboardInputLock.ZIndex = 199
        keyboardInputLock.Parent = gui

        -- Janela flutuante do teclado; permanece acima da trava de entrada.
        keyboardWindow = Instance.new("Frame")
        keyboardWindow.Name = "CelestialHubKeyboard"
        keyboardWindow.Size = UDim2.new(0, 846, 0, 418)
        keyboardWindow.AnchorPoint = Vector2.new(0.5, 0.5)
        keyboardWindow.Position = UDim2.new(0.5, 0, 0.5, 0)
        keyboardWindow.BackgroundColor3 = Color3.fromRGB(18, 17, 25)
        keyboardWindow.BorderSizePixel = 0
        keyboardWindow.Visible = false
        keyboardWindow.Active = true
        keyboardWindow.ZIndex = 200
        keyboardWindow.Parent = gui
        Instance.new("UICorner", keyboardWindow).CornerRadius = UDim.new(0, 12)
        -- Contorno externo roxo; as teclas usam bordas amarelas finas como na referência.
        local keyboardRGBStrokes = {}
        local keyboardStroke = Instance.new("UIStroke", keyboardWindow)
        keyboardStroke.Color = Color3.fromRGB(145, 55, 235)
        keyboardStroke.Thickness = 2
        table.insert(keyboardRGBStrokes, keyboardStroke)

        -- Escala única para redimensionar o teclado inteiro sem deformar o layout.
        local keyboardScale = Instance.new("UIScale")
        -- Tamanho inicial menor para celular; a bolinha permite ajustar livremente.
        keyboardScale.Scale = 0.55
        keyboardScale.Parent = keyboardWindow

        local keyboardTitleBar = Instance.new("Frame", keyboardWindow)
        keyboardTitleBar.Size = UDim2.new(1, 0, 0, 42)
        keyboardTitleBar.BackgroundColor3 = Color3.fromRGB(25, 23, 34)
        keyboardTitleBar.BorderSizePixel = 0
        keyboardTitleBar.ZIndex = 201
        keyboardTitleBar.Active = true
        Instance.new("UICorner", keyboardTitleBar).CornerRadius = UDim.new(0, 10)

        -- Arrastar pela barra superior para reposicionar o teclado.
        -- A posição fica guardada na própria janela e não é redefinida ao reabrir.
        local draggingKeyboard = false
        local dragInput = nil
        local dragStart = nil
        local windowStartPosition = nil

        keyboardTitleBar.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                draggingKeyboard = true
                dragInput = input
                dragStart = input.Position
                windowStartPosition = keyboardWindow.Position
            end
        end)

        UserInputService.InputChanged:Connect(function(input)
            if not draggingKeyboard then return end
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - dragStart
                keyboardWindow.Position = UDim2.new(
                    windowStartPosition.X.Scale,
                    windowStartPosition.X.Offset + delta.X,
                    windowStartPosition.Y.Scale,
                    windowStartPosition.Y.Offset + delta.Y
                )
            end
        end)

        UserInputService.InputEnded:Connect(function(input)
            if draggingKeyboard and (
                input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
            ) then
                draggingKeyboard = false
                dragInput = nil
                dragStart = nil
                windowStartPosition = nil
            end
        end)

        local keyboardTitle = Instance.new("TextLabel", keyboardTitleBar)
        keyboardTitle.BackgroundTransparency = 1
        keyboardTitle.Position = UDim2.new(0, 16, 0, 0)
        keyboardTitle.Size = UDim2.new(1, -62, 1, 0)
        keyboardTitle.Font = FONTE_TITULO
        keyboardTitle.Text = "Celestial Hub - Keyboard"
        keyboardTitle.TextColor3 = Color3.fromRGB(245, 245, 250)
        keyboardTitle.TextSize = 16
        keyboardTitle.TextXAlignment = Enum.TextXAlignment.Left
        keyboardTitle.ZIndex = 202

        local function criarBotaoTopo(texto, x, largura)
            local b = Instance.new("TextButton", keyboardTitleBar)
            b.Size = UDim2.new(0, largura, 0, 30)
            b.Position = UDim2.new(1, x, 0, 6)
            b.BackgroundColor3 = Color3.fromRGB(42, 40, 52)
            b.BorderSizePixel = 0
            b.Text = texto
            b.TextColor3 = Color3.fromRGB(255, 255, 255)
            b.Font = FONTE_TEXTO
            b.TextSize = 16
            b.ZIndex = 203
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 5)
            return b
        end
        -- Único botão da barra superior: fechar.
        local keyboardClose = criarBotaoTopo("X", -42, 30)

        local keyboardBody = Instance.new("Frame", keyboardWindow)
        keyboardBody.BackgroundTransparency = 1
        keyboardBody.Position = UDim2.new(0, 8, 0, 48)
        keyboardBody.Size = UDim2.new(1, -16, 1, -56)
        keyboardBody.ZIndex = 201

        local vimService
        pcall(function() vimService = game:GetService("VirtualInputManager") end)
        local shiftAtivo = false
        local keysPressionadas = {}

        local keyMap = {
            ["`"] = "Backquote", ["-"] = "Minus", ["="] = "Equals",
            ["["] = "LeftBracket", ["]"] = "RightBracket", ["\\"] = "BackSlash",
            [";"] = "Semicolon", ["'"] = "Quote", [","] = "Comma",
            ["."] = "Period", ["/"] = "Slash", ["Del"] = "Delete",
            ["Backspace"] = "Backspace", ["Caps Lock"] = "CapsLock",
            ["Tab"] = "Tab", ["Enter"] = "Return", ["Esc"] = "Escape",
            ["Ctrl"] = "LeftControl", ["Alt"] = "LeftAlt", ["Shift"] = "LeftShift",
            ["Space"] = "Space", ["Up"] = "Up", ["Down"] = "Down",
            ["Left"] = "Left", ["Right"] = "Right"
        }

        local function resolverKeyCode(label)
            local nome = keyMap[label] or label
            local ok, result = pcall(function() return Enum.KeyCode[nome] end)
            if ok then return result end
            return nil
        end

        local function enviarTecla(label, pressionada)
            local keyCode = resolverKeyCode(label)
            if not keyCode or not vimService then return end
            pcall(function()
                vimService:SendKeyEvent(pressionada, keyCode, false, game)
            end)
        end

        local function soltarTodasTeclas()
            for label in pairs(keysPressionadas) do
                enviarTecla(label, false)
                keysPressionadas[label] = nil
            end
            if shiftAtivo then
                enviarTecla("Shift", false)
                shiftAtivo = false
            end
        end

        -- Layout seguindo a referência do Delta Mobile, tecla por tecla:
        -- 1) Esc/F1-F12/Del; 2) `/1-0/-/=/Backspace;
        -- 3) Tab/QWERTY/[ ]/\\; 4) Caps/ASDF/; '/Enter;
        -- 5) Shift/ZXCV/,.//Shift; 6) Ctrl/Alt/Space/Alt/Ctrl + setas.
        -- As fileiras usam a mesma altura, espaçamento e ordem da imagem.
        local KEY_ROW_HEIGHT = 47
        local KEY_ROW_STEP = 56
        local KEY_GAP = 6
        local KEY_ROW_WIDTH = 824

        local rows = {
            {
                {"Esc",0.9},{"F1",0.9},{"F2",0.9},{"F3",0.9},{"F4",0.9},
                {"F5",0.9},{"F6",0.9},{"F7",0.9},{"F8",0.9},{"F9",0.9},
                {"F10",0.9},{"F11",0.9},{"F12",0.9},{"Del",1.5}
            },
            {
                {"`",0.9},{"1",0.9},{"2",0.9},{"3",0.9},{"4",0.9},{"5",0.9},
                {"6",0.9},{"7",0.9},{"8",0.9},{"9",0.9},{"0",0.9},{"-",0.9},
                {"=",0.9},{"Backspace",1.5}
            },
            {
                {"Tab",1.35},{"Q",0.9},{"W",0.9},{"E",0.9},{"R",0.9},{"T",0.9},
                {"Y",0.9},{"U",0.9},{"I",0.9},{"O",0.9},{"P",0.9},{"[",0.9},
                {"]",0.9},{"\\",1.2}
            },
            {
                {"Caps Lock",1.75},{"A",0.9},{"S",0.9},{"D",0.9},{"F",0.9},
                {"G",0.9},{"H",0.9},{"J",0.9},{"K",0.9},{"L",0.9},
                {";",0.9},{"'",0.9},{"Enter",1.75}
            },
            {
                {"Shift",2.05},{"Z",0.9},{"X",0.9},{"C",0.9},{"V",0.9},
                {"B",0.9},{"N",0.9},{"M",0.9},{",",0.9},{".",0.9},
                {"/",0.9},{"Shift",2.05}
            }
        }

        local function criarLinhaTeclas(row, rowIndex)
            local rowFrame = Instance.new("Frame", keyboardBody)
            rowFrame.Name = "LinhaTeclas" .. rowIndex
            rowFrame.BackgroundTransparency = 1
            rowFrame.Position = UDim2.new(0, 0, 0, (rowIndex - 1) * KEY_ROW_STEP)
            rowFrame.Size = UDim2.new(1, 0, 0, KEY_ROW_HEIGHT)
            rowFrame.ZIndex = 202

            local gap = KEY_GAP
            local totalWeight = 0
            for _, item in ipairs(row) do totalWeight = totalWeight + item[2] end
            local usableWidth = KEY_ROW_WIDTH - gap * (#row - 1)
            local x = 0
            for _, keyData in ipairs(row) do
                local label, weight = keyData[1], keyData[2]
                local keyWidth = math.floor(usableWidth * weight / totalWeight)
                local keyButton = Instance.new("TextButton", rowFrame)
                keyButton.Name = "Key_" .. label:gsub("%W", "")
                keyButton.Position = UDim2.new(0, x, 0, 0)
                keyButton.Size = UDim2.new(0, keyWidth, 0, KEY_ROW_HEIGHT)
                keyButton.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
                keyButton.BorderSizePixel = 0
                keyButton.Text = label
                keyButton.TextColor3 = Color3.fromRGB(245, 245, 245)
                keyButton.Font = FONTE_TEXTO
                keyButton.TextSize = 15
                keyButton.TextWrapped = true
                keyButton.ZIndex = 203
                Instance.new("UICorner", keyButton).CornerRadius = UDim.new(0, 7)
                local outline = Instance.new("UIStroke", keyButton)
                outline.Color = Color3.fromRGB(235, 190, 35)
                outline.Thickness = 1.0
                table.insert(keyboardRGBStrokes, outline)

                keyButton.MouseButton1Down:Connect(function()
                    if label == "Shift" then
                        if not shiftAtivo then
                            shiftAtivo = true
                            enviarTecla("Shift", true)
                        end
                    elseif label == "Caps Lock" then
                        enviarTecla(label, true)
                        task.delay(0.05, function() enviarTecla(label, false) end)
                    else
                        keysPressionadas[label] = true
                        enviarTecla(label, true)
                    end
                    keyButton.BackgroundColor3 = Color3.fromRGB(65, 57, 28)
                end)
                keyButton.MouseButton1Up:Connect(function()
                    if label ~= "Shift" and label ~= "Caps Lock" then
                        enviarTecla(label, false)
                        keysPressionadas[label] = nil
                    end
                    keyButton.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
                end)
                keyButton.MouseLeave:Connect(function()
                    if keysPressionadas[label] then
                        enviarTecla(label, false)
                        keysPressionadas[label] = nil
                    end
                    keyButton.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
                end)
                x = x + keyWidth + gap
            end
        end

        for rowIndex, row in ipairs(rows) do
            criarLinhaTeclas(row, rowIndex)
        end

        -- Linha inferior: Ctrl / Alt / espaço / Alt / Ctrl e setas em cruz.
        local bottomRow = Instance.new("Frame", keyboardBody)
        bottomRow.Name = "LinhaInferior"
        bottomRow.BackgroundTransparency = 1
        bottomRow.Position = UDim2.new(0, 0, 0, 282)
        bottomRow.Size = UDim2.new(1, 0, 0, 48)
        bottomRow.ZIndex = 202

        local function criarTeclaInferior(label, x, y, width, height)
            local b = Instance.new("TextButton", bottomRow)
            b.Name = "KeyBottom_" .. label:gsub("%W", "") .. tostring(math.floor(x * 1000))
            b.Position = UDim2.new(0, x, 0, y)
            b.Size = UDim2.new(0, width, 0, height)
            b.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
            b.BorderSizePixel = 0
            b.Text = label
            b.TextColor3 = Color3.fromRGB(245, 245, 245)
            b.Font = FONTE_TEXTO
            b.TextSize = 14
            b.ZIndex = 203
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 7)
            local stroke = Instance.new("UIStroke", b)
            stroke.Color = Color3.fromRGB(235, 190, 35)
            stroke.Thickness = 1.0
            table.insert(keyboardRGBStrokes, stroke)
            b.MouseButton1Down:Connect(function()
                keysPressionadas[label] = true
                enviarTecla(label, true)
                b.BackgroundColor3 = Color3.fromRGB(65, 57, 28)
            end)
            b.MouseButton1Up:Connect(function()
                enviarTecla(label, false)
                keysPressionadas[label] = nil
                b.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
            end)
